quests[65419] = { id = 65419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protoform Synthesis", description = "<Pocopoc jumps around anxiously. When you completed your research into the basics of Dealic, it got very excited and it is urging you to follow it somewhere else in this realm.>", progress = "<Pocopoc looks between you and the console excitedly.>", completion = "<Pocopoc points to some controls on this device, and you understand just enough Dealic to glimpse its purpose in bringing you here. With some materials found across Zereth Mortis and Pocopoc's help, you can trigger this machine to create fully realized beings based on specific schematics.>", objectives = "Escort Pocopoc to the Protoform Synthesis Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65420] = { id = 65420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Call", description = "Oh no... No no no... What have I done?\n\nThe elders will never take me back. They shall cast me out as they did Firim.\n\nPlease, outsider, speak to Elder Amir in Pilgrim's Grace. Give him my thanks for sending you, and tell him all that has happened here. He will understand why I must never return.", completion = "Tahli is alive? And you preserved an automa archive with her help?! Oh, my. That is... a lot to take in.\n\nAnd, of course, her guilt has prevented her from returning home. Oh, Tahli.", objectives = "Speak to Elder Amir in Pilgrim's Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65421] = { id = 65421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Climb Every Mountain", description = "Hope ye are a quick study, {class}. 'Cause I got no time for a lesson! \n\nGrab a pack and find a path tae the top o' that peak.\n\nOnce yer up there, toss this parachute to our pal Yips. Poor kid got stuck on some vines when these air elementals crashed our plane!\n\nQuickly now, so we can get outta here!", progress = "Hurry on, now! Yips can't hold fer long!", completion = "Nice climbing! Yips owes ye a drink or two!\n\nOh, the elementals? Nah, don't worry 'bout 'em. This is OUR adventure!\n\n<Rocky resumes gleefully shooting bullets through the air elementals.>", objectives = "Grab the Climbing Gear, find a handhold, and climb up the cliff to rescue Pathfinder Yips!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65422] = { id = 65422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Hunting Ain't Easy", description = "I can see it yer eyes: Ye got the urge to climb to the top of this here mountain and find out what's on the top!\n\nUs climbers always recognize each other. We won't let any mountain make us feel small, right?\n\nWell, good fer ye I brought plenty of climbing gear. Grab a pack and find a path to the top!", sourceObjective = "Grab the Rock Climbing Gear, then find a handhold and climb to the top of the mountain without losing your grip!", sourceObjectiveStatus = "unverified-source-field" }
quests[65424] = { id = 65424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever You Sayaad", description = "As my master, you should know - I'm fairly flexible when it comes to... matching preferences. \n\n<The demon gestures to themselves.>\n\nIf you're not a fan of this, then I could always just stick to a singular appearance that I have that will haunt your dreams. One of your mentors should be able to teach you how to adjust your summoning ritual.\n\nOf course, if you want to leave it up to me... Well, I can guarantee a good time either way.", completion = "An interesting proposal... One I may need to try out myself.\n\nSpeak with me whenever you wish to adjust your summoning ritual. I believe I know what they were referring to.", objectives = "Speak with Kazak Darkscream in Orgrimmar about adjusting your Summon Succubus spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65425] = { id = 65425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever You Sayaad", description = "As my master, you should know - I'm fairly flexible when it comes to... matching preferences. \n\n<The demon gestures to themselves.>\n\nIf you're not a fan of this, then I could always just stick to a singular appearance that I have that will haunt your dreams. One of your mentors should be able to teach you how to adjust your summoning ritual.\n\nOf course, if you want to leave it up to me... Well, I can guarantee a good time either way.", completion = "What a curious concept. I had no idea that Succubi were capable of such a thing.\n\nSpeak with me whenever you wish to adjust your summoning ritual. I believe I know what they were referring to.", objectives = "Speak with Evelyn Thorn in Stormwind about adjusting your Summon Succubus spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65426] = { id = 65426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Component", description = "Maw Walker! Look.\n\nWe have been studying this automa component for some time. Its cyphers are similar to those of the components near and within the Protoform Repository.\n\nKodah's last effort should not be in vain. Please return this component to the repository that our friend restored.", progress = "The mortal seeks protoform synthesis.", completion = "Greetings, Architect.", objectives = "Pick up the Protoform Catalyst and return it to the Protoform Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65427] = { id = 65427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Architect", description = "The architects prototype designs to fulfill the purposes of the First Ones. \n\nThis archive contained many such designs.\n\nA number of design entries are lost or corrupted due to the Maw invasion. \n\nAn untouched design lattice and tools are detected nearby. The mortal will retrieve them to begin the synthesis process.", progress = "Have the necessary materials been located?", completion = "Success. \n\nThe Protoform Repository is now restored.", objectives = "Collect 1 Cervid Lattice and 3 Protoform Tools and bring them to the Servitor Interface in the Protoform Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65431] = { id = 65431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Research: Aealic", description = "Maw Walker, you have made some wondrous discoveries, but there are still secrets to uncover.\n\nYou have taken the first step, in unlocking the console and I believe that you are ready to take another.\n\nPlease go investigate the console and see what new piece of the pattern unfolds itself to you.", progress = "Go see what secrets await you!", completion = "New knowledge! The First Ones truly did leave such marvelous insights.", objectives = "Investigate the Cypher Console in Exile's Hollow further.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65432] = { id = 65432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Research: Dealic", description = "<The console hums with a mysterious energy.>", progress = "<Further investigation may be required.>", completion = "<A strange energy surrounds the console.>", objectives = "Further investigate the Cypher Console in Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65433] = { id = 65433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Research: Trebalim", description = "<The console hums with a mysterious energy.>", progress = "<Further investigation may be required.>", completion = "<A strange energy surrounds the console.>", objectives = "Further investigate the Cypher Console in Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65435] = { id = 65435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon Isles Await", description = "Heroes of the Horde, I bring news. The Dragon Isles are awakening!\n\nThe Isles went dormant in the wake of the Sundering. But now, at long last, they have called my kin and me  home.\n\nWhile the Isles hold many wonders, it is also a perilous land. We will require the aid of our mortal allies to reclaim our legacy.\n\nI am about to present the Aspects' invitation to the Horde Council in Orgrimmar. Meet me there and we shall see what they have to say.", completion = "I am grateful you have answered the call. Your courage will be welcome on the journey ahead.", objectives = "Meet Ebyssian in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65436] = { id = 65436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon Isles Await", description = "Wondrous news, my friend! The Dragon Isles are awakening!\n\nMy people left our lands dormant in the wake of the Sundering. But now, at long last, we feel the call to home.\n\nWhile the Isles hold many wonders, there are perils as well. We will require the aid of our mortal allies in order to reclaim our legacy.\n\nMeet me in Stormwind. I must present the Aspects' invitation to the Alliance.", completion = "The Aspects' invitation extends to you as well, friend.", objectives = "Meet Wrathion in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65437] = { id = 65437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspectral Invitation", completion = "I am honored that you will journey to the homeland of dragonkind.\n\nOne of your allies is eager to assist you in preparing for what lies ahead.", objectives = "Speak with Ebyssian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65438] = { id = 65438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awesome Quest Start", description = "The start of the Azure Span." }
quests[65439] = { id = 65439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers on the Winds", progress = "Our journey begins with you.", completion = "Unsettling news indeed, but you had to know of the peril we face.", objectives = "Speak with Archmage Khadgar outside Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65443] = { id = 65443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionary Coordination", description = "Pleasure to meet you, I am Naleidea Rivergleam.\n\nThe invitation to visit the Dragon Isles is quite an exciting prospect. Don't you agree?\n\nThe Reliquary has combined forces with our expeditionary counterparts to help coordinate our efforts. As a member of the Dragonscale Expedition, it is my honor to welcome you.\n\nThough first we must gather a few more members for our journey. Shall we begin?", progress = "Have you spoken with the others yet?", completion = "I believe this expedition shall be a great success.", objectives = "Recruit explorers, artisans, and scholars throughout Orgrimmar for the expedition to the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65444] = { id = 65444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Dragon Isles!", description = "Our preliminary expedition has made landfall in the Dragon Isles.\n\nThanks to the efforts of those brave Dragonscale Expedition members, we've established a protected landing site in the Dragon Isles and made contact with the dragonflight's embassy.\n\nAre you prepared to accompany us on our next voyage to the Dragon Isles?", completion = "Welcome to the Dragon Isles!", objectives = "Ride the Defiant Dragonscale to the Dragon Isles from the zeppelin tower outside Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65445] = { id = 65445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Resourcing", description = "Devourers are consuming neomotes.\n\nWe need neomotes for necessary creation work. Without them, we are unable to complete our work.\n\nEliminate the devourers and retrieve the neomotes.", progress = "Have you collected the neomotes?", completion = "You have completed the task. Thank you for your assistance.", objectives = "Obtain 30 Neomote Residue and 3 Solidified Neomotes from Devourers in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65448] = { id = 65448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Return to Grace", description = "<With the temple restored and its defenses back online, the Wellspring should be safe from the devourers. Conservator Olem will want to know what you've done here.>", progress = "You return--and as I expected, you were successful.", completion = "As I thought--your arrival was by the design of the First Ones. I look forward to the legacy you forge in this land of our creators.", objectives = "Speak to Conservator Olem and give him the good news.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65451] = { id = 65451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Materials", description = "These proto-drakes are unlike any I've seen before on Azeroth.\n\nTheir scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. \n\nMy artisans--all of them--are clamoring to get their hands on some of those scales to work with.\n\nStart with the whelps. The smaller scales should be more pliable until we've mastered our techniques with them.", progress = "Have you got the scales yet? The alchemists are getting antsy, and that always makes me nervous.", completion = "<Boss Magor carefully studies the scales.>\n\nOur artisans will put these to good use. Thank you.", objectives = "Collect 20 Primal Proto-Whelp Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65452] = { id = 65452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers in Peril", progress = "Are the expedition members safe?", completion = "The dragons are not here to meet us as Ebyssian said they would be...", objectives = "Rescue 3 Dragonscale Expedition members in the Wild Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65453] = { id = 65453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Pests", description = "<Cindrethresh glances suspiciously at the proto-dragons lurking on the ridge behind her.>\n\nI'd swear that those proto-dragons edge closer to camp every time I turn my back...\n\nThose are not the dragons Ebyssian invited us here to meet.\n\nProto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return.\n\nCull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", progress = "Always keep an eye on the skies.", completion = "That may dissuade them from attacking the expedition camps for a time.\n\nIt's eat or be eaten in the Dragon Isles, {name}. You'd do well to remember that.", objectives = "Kill 8 Primal Proto-drakes on the Wild Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65456] = { id = 65456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Lost Firim", description = "I was gathering data here when your portal opened. The disruption activated these gate-locking mechanisms. \n\nIt is only fair for you to gather the gate keys, yes? We shall speak while you search.", progress = "And now, onward.", completion = "You are stronger and more patient than you look.", objectives = "Help Firim open the gate into Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65460] = { id = 65460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Cantaric Protolock", description = "Maw Walker, it appears that Pocopoc has learned the Cachial skill. This grants you access to the Caches of Creation. You will find several types of these caches all throughout Zereth Mortis.\n\nIn order to aid me with my research, you will need to be able to decode various cyphers such as the Cantaric Protolock. \n\nNow, let me show you what you need to do to assist me.", progress = "Good, now take your expanded knowledge out into the field.", completion = "Well done, Maw Walker.\n\nI am sure that with enough energy and effort your companion will be able to help you overcome these challenges, if they become a struggle for you.", objectives = "Complete the Cantaric Protolock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65461] = { id = 65461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Mezzonic Protolock", description = "In order to aid me in my research, you will need to decode various Progenitor cyphers like the Mezzonic Protolock.  Now, I will show you what you need to do.", progress = "Use this knowledge to collect more data from the field.", completion = "Use this knowledge and collect more data from the field, Maw Walker.\n\nThere is still one more Cache of Creation that I must instruct you on.", objectives = "Complete the Mezzonic Protolock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65463] = { id = 65463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wellspring of the First Ones", description = "A mortal, here? How unusual! Welcome to Pilgrim's Grace. Would that you had arrived under better circumstances. Pilgrims usually travel here to visit the sacred Wellspring of the First Ones. \n\nUnfortunately, the wellspring has gone dry. I do not understand it. The creations of the First Ones should be infallible! \n\nThis situation is as unusual as your arrival--perhaps you can lend your aid? Travel to the wellspring and speak to Conservator Olem.", completion = "A mortal, here? The designs of the First Ones are mysterious.", objectives = "Speak to Conservator Olem about the Wellspring's problem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65466] = { id = 65466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Fugueal Protolock", description = "In order to aid my research you will need to decode various Progenitor cyphers like the Fugueal Protolock. This is a most difficult cypher, I will show you what you need to do.", progress = "Use this knowledge and collect more data from the field.", completion = "Well done, Maw Walker. That was truly an impressive effort.\n\nRemember, that if you do struggle with these protolocks, your companion can help you overcome them if they have enough energy.\n\nNow take your expanded knowledge out into the field.", objectives = "Complete the Fugueal Protolock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65467] = { id = 65467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turkey Soul", description = "<The Turkey Soul is bold and fierce. The shape of the turkey will be yours to call upon.>", completion = "Ooh, a turkey! You can gobble like one now, too!", objectives = "Bring the Turkey Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65475] = { id = 65475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolling in the Screech", description = "<You pull a scrap of parchment from the gooey, blood-soaked satchel of the Roc-Muncher. All you can make out is imagery of harpies devouring large eggs.\n\nYou're positive the thick, unintelligible scratch marks will make plenty of sense to your favorite senior ornithologist, Harleen Chirpsnide.>", progress = "Back from the caves already?", completion = "Ho, now! That's certainly no dinner menu you're holding!\n\nOr maybe it is...", objectives = "Bring the Screechflight Scroll to Harleen Chirpsnide in the Bluefeather Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65486] = { id = 65486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picture Perfect", description = "Sorry if ya be waitin' long. Sometimes I get lost in de telescope.\n\nDo ya ever find da world be easier understood from a distance? No interference, just nature goin' about its business without us...\n\n<Akunda the Cataloger sighs.>\n\nI see Coralie gave ya a camera. Good.\n\nTake a ride down the river with Fren, and take photographs of some wildlife in dey natural habitats for me to study.", progress = "Fren will row the raft for ya. Don't worry, she's da very best!", completion = "<Akunda flips through the photographs quickly, intently analyzing each one.>\n\nRe-mark-a-ble! Surprisin' too. I've much to learn from these; so many new specimens to document!\n\nThank you, {name}!", objectives = "Ride the Cataloger's Raft with Fren and take pictures of local wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65490] = { id = 65490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Excrement", description = "The harpies are a nice surprise and all, but I came to these mountains for one reason and one reason only: EXCREMENT!\n\nSpecifically, the excrement of bluefeather rocs that's then been eaten and digested by bugs. Scarab stomach juices enhance the explosive nitrogen content by tenfold! At least!\n\nHere, take this Chirpsnide Auto-Excre-Collector. Stomp on the scarabs crawling around the cave floor, and use the Collector to reap the rewards.\n\nBring it back full and we can start the real fun: EXPLOSIONS!!", completion = "Oh, yes! Quality stuff!!\n\nHave you thought about doing this work professionally, {name}?", objectives = "Fill Professor Chirpsnide's Auto-Excre-Collector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65504] = { id = 65504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonhawk Soul", description = "<The Dragonhawk Soul is nimble and resilient. The shape of the dragonhawk will be yours to call upon.>", completion = "Ah, the dragonhawk. This shape is now yours to call upon.", objectives = "Bring the Dragonhawk Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
