quests[65518] = { id = 65518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bee Soul", description = "<The Bee Soul is protective and spry. The shape of the bee will be yours to call upon.>", completion = "Ooh, a bee! Now you can buzz like one too!", objectives = "Bring the Bee Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65519] = { id = 65519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snail Soul", description = "<The Snail Soul is cautious and patient. The shape of the snail will be yours to call upon.>", completion = "Ooh, a snail! Now you can crawl like one too!", objectives = "Bring the Snail Soul to Choofa in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65563] = { id = 65563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Kasea", description = "Hope ye don't mind, but I used some of your materials to craft something Kasea has been asking me for.\n\nWould you mind bringin' it over to her?", completion = "Thurgaden finally made it, did he? And sent it with just the right person!", objectives = "Deliver the Bladed Helmet to Kasea Angerforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65564] = { id = 65564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Fiery Boy", description = "I train hounds of all types, 'long as they're fiery. I've trained up Grimhowl here since he was a wee pup, but a life in Shadowforge City isn't what he's meant ta live!\n\nGrimhowl needs that special someone to bond with, someone who'll take him 'round all of Azeroth. Perhaps that could be you?\n\nTake some time to get to know him. I think Grimhowl will warm up to ye real quick!", progress = "If ye bond with this beastie, you'll have a loyal companion for life!", completion = "They like ye, they really like ye! Treat this pup with love and they will be your adventuring partner for years to come.", objectives = "Bond with Grimhowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65594] = { id = 65594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Mountain Out of a Gnoll Hill", description = "Stupid decay thinks it in charge, but me in charge. We kill it now. Me turned ooze into friends.", progress = "IT'S SO BOUNCY!", completion = "You live this long? Good meat.", objectives = "Destroy 3 Decay Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65595] = { id = 65595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Bad Apple", description = "Rot starve gnolls.\n\nRot hurt friends.\n\nWe kill rot now. Is what Mon-Arks do.", completion = "Me lead gnolls to better hunt now. You... not so bad. Gnolls hungry though, and you still meat.\n\nLeave. Me no chase.", objectives = "Kill the Root of Decay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65606] = { id = 65606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Maruuk", description = "Your deeds to further the interests of the clan have not gone unnoticed. \n\nReturn to Maruukai, I have prepared some supplies to further assist you in your work with us.", completion = "You honor us with your deeds, I will tell the elders of your work. Take these supplies, may they aid you in the hunt!", objectives = "Speak with Agari at Maruukai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65613] = { id = 65613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Iconic, Draconic Look", progress = "Tap into your draconic heritage.", completion = "You have a noble visage indeed, {name}. Most distinctive.\n\nI do not know why your visage is unique from that of a dragon. Perhaps when we learn more of your past, the answer will present itself.\n\nBut for now, we must prepare for the journey ahead.", objectives = "Adopt a Visage Form.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65615] = { id = 65615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Intrusion", description = "That beacon ahead--I am certain it was not there before we were imprisoned.\n\nSpellcraft is not my forte, but I know arcane magic when I see it. The same magic used by the blue dragon in the creche.\n\nHe said a name... Malygos. It sounds so familiar, but the Earth-Warder's teachings feel distant. Fragmented.\n\nIf this Malygos put us into stasis, perhaps the arcane beacon was placed on his orders.\n\nInvestigate the area and report back. Ensure the beacon cannot be used to call in enemy reinforcements.", progress = "There is powerful magic in the air. But it is ancient, fading.", completion = "<Azurathel listens intently as you tell him what you witnessed.>\n\nSo there were beacons placed outside the other creches as well.\n\nOur allies are in peril. We must reach them!", objectives = "Investigate the beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65625] = { id = 65625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jailer's Gauntlet", description = "Maw Walker! I have been looking for you. \n\nWord is there is a new gathering of the Jailer's forces in Torghast. I'm not sure what they are doing, but it can't be good.\n\nPerhaps you should put an end to their plans?", objectives = "Enter the new portal in the Torghast Lobby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65640] = { id = 65640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cervid Soul", description = "<The Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>", completion = "Ah, the cervid. This shape is now yours to call upon.", objectives = "Bring the Cervid Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65649] = { id = 65649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Deal", description = "Ah, Maw Walker! Opportunities abound now that you have found a way into Zereth Mortis. \n\nLet us discuss further business, yes?\n\nWe have an interest in observing the potential this new pathway has provided. I trust you will procure what we require. Do not let anyone get in your way.\n\nIf this is not agreeable, I am certain I can find someone else to solve both of our problems.", progress = "I trust you are not returning empty-handed, yes?", completion = "Good! You have done well.\n\nHere, a token of our appreciation. Your contributions were well observed.", objectives = "Collect 150 Protoplasmic Thread in Zereth Mortis, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65652] = { id = 65652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from the Matriarch", description = "Greetings, {name}.\n\nLet us not mince words--you are urgently needed in Silvermoon. \n\nWe're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line!\n\nMeet me in the Hall of Blood, and we will get you a full briefing.", completion = "Good, you made it.\n\nLet us begin.", objectives = "Meet Lady Liadrin in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65653] = { id = 65653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory for the Sin'dorei", description = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you.\n\nMeet me back in the Hall of Blood. Silvermoon is grateful for your bravery.", completion = "This is not the end of the Scourge, but it is gratifying to drive the threat from our lands with such tenacity.\n\nSilvermoon is grateful for you this day.", objectives = "Return to Lady Liadrin in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65655] = { id = 65655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Wolf", description = "An alarming rumor has reached me, thanks to our spies.\n\nThe Forsaken are mustering in Tirisfal Glades. For what purpose, I do not know. Notably, Calia Menethil has gone there as well.\n\nWe must know more of what they are up to, now that the accursed Banshee Queen no longer unites them.\n\nGo, don a disguise and see what you can discover. Observe everything. And if there is opportunity to gain their trust and learn more, do as they ask.\n\nI eagerly await your report.", completion = "<Calia studies you closely for a moment, a smile on her lips.>\n\nYou will fit right in. And do not fear, I will not reveal you to the others here.\n\nBut please understand, many of the Forsaken were once citizens of Lordaeron. They are trying to do something extraordinary here, and I promise, if you play along and help them, it will be worth the effort.\n\nIt will make for a better Azeroth.", objectives = "Meet Calia Menethil in Brill, Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65656] = { id = 65656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Lordaeron", description = "With the Shadowlands healing, it is time to turn our attention to matters close to home again, on Azeroth.\n\nThe Forsaken are mustering in the ruins of the kingdom of Lordaeron. They seek to reclaim as much as they can of the Tirisfal Glades, to finally put the destruction left by the Fourth War behind them.\n\nAnd I intend to assist them in any way I can.\n\nI also know that for the Horde, I have much to prove. Come, join me in Brill and we can help the Forsaken together.", progress = "We all bear the weight of our history.", completion = "I was always fond of Brill.\n\nMuch remains to be done, but it is heartening to see the progress made in rebuilding here.", objectives = "Meet Calia Menethil in Brill, Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65657] = { id = 65657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assemble the Forsaken", description = "It's heartening to see progress has been made in rebuilding Brill, but this is only a first step. The ruins of the capital remain inaccessible because of the blight.\n\nAnd here is where I hope you will aid the cause.\n\nRestoring as much of the land as possible will require a gathering of minds all working toward a singular purpose.\n\nA number of influential figures have risen to prominence among the Forsaken. Please help bring them together so we can meet and discuss the path forward.", progress = "Everyone is working hard to get back on their feet. Might not be the feet they started out with, but they work.", completion = "Looks like we're ready to get started.\n\nI don't think there have been this many Forsaken in one place since... well, Darkshore.\n\nBut we are in our own lands now, and it's time we take care of our own.", objectives = "Assemble Dark Ranger Velonara, Lillian Voss, and Master Apothecary Faranell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65658] = { id = 65658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Land is Ours", description = "The plague unleashed during the war has tainted the land and disturbed the dead. That is to say, more so than they already were.\n\nWe have worked hard to rebuild, but our people cannot complete their efforts while under threat.\n\nMy first duty is to ensure the safety of the Forsaken. I will meet with the others as Calia requests, but first you must help me eradicate some of these Blighted.", progress = "We need the pressure off of Brill so we can continue to rebuild.", completion = "That should give our guards some breathing room. Metaphorically speaking, of course.\n\nThank you for the help, {name}.", objectives = "Slay Blighted Soldiers in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65659] = { id = 65659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blight Congress", description = "We, the Forsaken, have been through a lot since the destruction of Lordaeron. But we're determined to keep our home.\n\nWhy should we give up what we've fought so hard to carve out for ourselves?\n\nCalia is still a relative newcomer in some ways, but obviously she's known to our people. How could she not be, as the sister of Arthas himself?\n\nI hope we can move forward, and that she can really help. Her voice could be a powerful one, if she is really truly committed to the people.", completion = "I expected that my presence might cause friction. But I'm grateful to Lilian for her mediation, and for giving me the chance to show that I am committed to helping the Forsaken people.\n\nBut now, I must prove it.", objectives = "Listen to the Forsaken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65660] = { id = 65660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk of Faith", description = "I promised that I would help, and I shall. We need that pure sample of the plague afflicting Lordaeron, but we cannot put anyone else at risk.\n\nCome with me. I will call forth a shield of Holy Light to safeguard us deep into the blighted area so that we can collect that sample.\n\nThis spell will require my full focus. I'll trust you to protect us from anything that might try to stop us.\n\nAre you with me?", progress = "I guess I should have faith.", completion = "That's something you don't see every day.", objectives = "Protect Calia inside her shield and collect the pure plague sample.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65661] = { id = 65661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consulting Our Allies", description = "I hope Calia is right about these lords of Maldraxxus. That they know how to deal with this sort of powerful plague.\n\nWe've only got one plague eater left, too, but Faranell says he can replicate more of them as long as they're strong enough to survive.\n\nLet's get to the Shadowlands.", completion = "You carry a rather nasty example of the unchecked and unfettered ambition of a plague-maker.\n\nI trust the creator of this monstrosity has already been purged. What would you ask of the houses of Maldraxxus?", objectives = "Speak to Margrave Sin'dane in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65662] = { id = 65662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House of Plagues", description = "The one with the knowledge you seek is a survivor of the House of Plagues. You already know him.\n\nPlague Deviser Marileth may not be the most lucid of conversationalists, but he will know what to do with your plague.\n\nFind him near the ruins of that fallen house. But be wary! Many things lurking there could end your existence without a hint of concern.", completion = "Hello, my favorite apprentice! \n\nSay, you look a tad wan. Are you certain you're getting enough sleep?", objectives = "Meet Plague Deviser Marileth in the House of Plagues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65663] = { id = 65663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed the Eater", description = "The House of Plagues has suffered calamity, much like Lordaeron. I hope that our work and effort here will reverse some of that destruction.\n\nBut first, we must reach farther into the House of Plagues so we can strengthen the capabilities of Faranell's plague eater.\n\nAny slime or creature you slay will surely help it gain fortitude.", progress = "We all have something we can contribute.", completion = "The Plague Eater is looking so much stronger already. I think Master Apothecary Faranell would be pleased.", objectives = "Slay Slimes and Plaguerocs in the House of Plagues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65664] = { id = 65664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Plague", description = "Your little friend there looks hungry! Not to worry, I know just what to feed it. Soon it will grow big and strong and be able to eat all the plague it can.\n\nThere are various concoctions nearby that will give it bolstering properties. And every color is a different flavor!\n\nI will take the plague sample you brought me deeper into the House of Plagues, to see what else we can learn. Meet me there, and let your plague eater dine in style!", progress = "Every color is a different flavor!", completion = "Did you see that? What a fearsome plague sample you brought me!\n\nIt hit me in the head and quite nearly killed your friends, apprentice. Marvelous!", objectives = "Absorb different Concoctions in the House of Plagues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65665] = { id = 65665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embodiment", description = "What a nasty little plague you've brought me, apprentice. Must've been concocted by a true sadist.\n\nTo study the sample, I gave it form. But the ungrateful thing turned on me and attacked, completely unprovoked! \n\nIt's shuffled a bit further on into the House. I hate to say it, but I believe this one must be put down before it is allowed to grow any stronger... or larger.\n\nLook on the bright side. If your plague eater manages to survive, it'll be attuned to your particularly terrible form of blight.", progress = "Have you disposed of that manifestation?", completion = "Despite all the trouble that sample gave us, I think I actually have a little bit of hope now.", objectives = "Slay the Lordaeron Blight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65666] = { id = 65666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Brill", description = "We've strengthened our plague eater, and now it looks ready to take on a much, much bigger meal.\n\nLet's get it back to Faranell. He said he can replicate its properties and disperse plague eaters all across the ruins.\n\nThen maybe, just maybe, we can set foot in our home again.\n\nHere, take my hearthstone. It'll bring you back to Brill.", progress = "What have you brought me?", completion = "Wonderful! Not only did you manage not to lose my plague eater, you brought it back stronger than ever!\n\nNow, witness the genius and rapidity of my machines. There will be more than enough plague eaters to spread across the surface of the Undercity.", objectives = "Return to Master Apothecary Faranell outside of the Ruins of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65667] = { id = 65667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Remedy of Lordaeron", description = "The time has come. By the Light, I pray our plan works.\n\nMaster Apothecary Faranell's wagons have reproduced the plague eater many times over, and the bats are ready to deploy them.\n\nIf you see a place where our forces could spread even more of the remedy, you can signal them with a flare.\n\nTake to the skies, and let's put an end to this blight. For Lordaeron, and for the Forsaken.", completion = "We did it. By working together, we've cleared the surface level of the deadly plague cloud.\n\nIt will take more time to clean up the lower reaches of the Undercity, but it's a fine start.", objectives = "Mount a Shadowbat and deploy Plague Eaters in the Ruins of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65668] = { id = 65668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Desolate Council", description = "By combining our knowledge and expertise, we've restored the surface of the Undercity to the Forsaken.\n\nIt was only possible by setting aside our distrust and acting for the good of our people. Now it's time to make this council official.\n\nWe are no longer the same undead that followed and served Sylvanas Windrunner. From here on, we lead ourselves, with the same spirit of independence and pride we've had since we reclaimed our free will.\n\nIt's time for a new future, with new leadership.", progress = "Hope, and fresh air, have been restored.", completion = "I am greatly honored that they have accepted me as part of the new leadership of the Forsaken. \n\nI swear that I will do my best to protect and preserve the people, no matter where they come from, or what form of undeath has created them.", objectives = "Witness the formation of the new Desolate Council.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65669] = { id = 65669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Greymane", description = "Thank you for all of your assistance, leading to this historic moment.\n\nI believe there may be others who are interested in what happened here. Please, carry this letter, and my well wishes, when you return to them.", progress = "What happened with the Forsaken?", completion = "They did WHAT?\n\nAnd Calia has proposed a discussion on the return of Gilneas?\n\nYour ability astounds me, {name}. Well done.", objectives = "Deliver Calia's letter to Genn Greymane in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65674] = { id = 65674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is This Thing?", description = "<The ambiguous essence in your hands looks as if it could serve a variety of purposes. In fact, it almost seems to radiate possibility.>\n\n<Perhaps Firim may have some answers about this.>", completion = "Oh, now this is a most interesting find indeed, mortal.\n\nI have encountered such material in my research before. In theory, it can alter the fate of various objects--unlocking their potential, as it were. Curious, no?\n\nI will keep this essence as I have need of it. In exchange, I will share with you the knowledge on how to use similar materials in your own creations.", objectives = "Bring the Unformed Essence to Firim in Exile's Hollow.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65680] = { id = 65680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schematic Reassimilation: Heartbond Lupine", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", completion = "Excellent. With this schematic and the right components, a new song can begin here to accompany you.", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65686] = { id = 65686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Azure Span", description = "Greetings, {name}! \n\nPakina and I are here on behalf of the Kirin Tor looking for aid. \n\nThe Kirin Tor are working to safeguard the wild arcane magic located all throughout the Azure Span.\n\nKalecgos, the Aspect of the blue dragonflight and one of our leaders, needs aid in reclaiming the Azure Oathstone there as well.\n\nIf you're willing to help, keep traveling along the road to find Glania of the Blessed Ones.\n\nShe can direct you to where you can help the most.", completion = "Excellent, an adventurer. I can fill you in on the details before I have to learn to... fish.", objectives = "Meet with Glania of the Blessed Ones within the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65687] = { id = 65687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Up", description = "Some of the other disciples are... very mean.\n\n<Ingot rubs a fresh wound on his snout.>\n\nIt used to not be like that, but when Cygenoth came, he said \"We should value strength above all else\". Now everybody fights all the time.\n\nI try to fight back, but their hides are too thick... and I'm too small.\n\nBut not you! You must fight bullies all the time. Maybe you can help?", progress = "The Worldbreakers aren't all bullies. Promise!", completion = "Those snagglescaled clods won't be hurting anyone else! The Earth-Warder thanks you! \n\nOh. And me. I thank you too.", objectives = "Slay 12 Worldbreaker Dragonkin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65688] = { id = 65688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting Kalecgos", description = "I fear we will have to split our attention. The Primalist threat to the east must be handled.\n\nI must ask you travel to the Azure Archives in my stead to aid Kalecgos in reclaiming the Azure Oathstone.\n\nYou'll need to pick up a few supplies to help you with whatever is happening there.\n\nSpeak with our portal quartermaster, they ought to have something that can aid you along the way. \n\nGood luck, {name}. Kalecgos will appreciate the aid.", progress = "I'm relieved to have any help. I know Khadgar and the others must be quite busy with the Primalists.", completion = "Khadgar is wise to redirect his efforts towards the Primalists.\n\nBut now... we've got a lot of work to do here.", objectives = "Get the Bag of Helpful Goods, then meet Kalecgos at the base of the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65689] = { id = 65689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Many Images of Kalecgos", description = "Good to formally meet you, {name}. My name is Kalecgos, Archmage of the Kirin Tor and Aspect of the blue dragonflight.\n\nI'm having difficulty repairing the Azure Archives to reclaim the Azure Oathstone. I could use an extra pair of physical hands.\n\nI'm currently up in the archives themselves. I was able to reactivate the pylon outside, which should allow you to traverse up here.", progress = "Glad to see you've made it.", completion = "Let's get to work. It's imperative to reclaim the Azure Oathstone.", objectives = "Use the Crystal Pylon to reach the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65690] = { id = 65690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cultist's Misgivings", description = "Another outsider arrived yesterday. She called herself an \"emissary\" for the red dragonflight and asked for an audience with our leader, the Voice of Neltharion. \n\nBut the Voice got terribly mad. He said that the Earth-Warder was testing us, and that we had to execute her!\n\nI know we're not supposed to trust outsiders, but we don't have to kill them! Please, help me save her.", completion = "This hatchling asked for your help?\n\n<Ayasanth exhales with relief.>\n\nPerhaps we can save the Worldbreakers after all.", objectives = "Locate Ayasanth in Smoldering Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65691] = { id = 65691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of His Wings", description = "The Voice of Neltharion resides below, spreading lies amongst his followers. \n\nHe appears to be dragonspawn like me. but his Draconic is clumsy--fit for the unscaled. \n\nI suspect duplicity: an illusion, perhaps. If we can subdue him, I'm certain the truth will out.", completion = "We quenched the last embers of the Twilight's Hammer today. But the Worldbreakers are another matter--these scaleborn will find new explanations for their misfortune, new myths, and new leaders. \n\nMy kin and I will watch over them. Should another Voice rise, we will intervene.\n\nYou've done a good thing this day.", objectives = "Confront Cygenoth, Voice of Neltharion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65700] = { id = 65700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Control", description = "Your timing is most excellent.\n\nIt appears one of my traps captured a rather curious creature moments ago. I dare not investigate, but you... you can do this for me.\n\nTake Pocopoc along with you. Perhaps there are secrets yet to be discovered.", progress = "Find something of interest?", completion = "Pocopoc is most intriguing, yes? I do wonder the extent of its capabilities.", objectives = "Examine the curious creature outside of Exile's Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65701] = { id = 65701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservation, Augmentation, or Devastation", description = "If what these dragons say is true, then a great battle is upon us. We need you focused and strong, evoker.\n\nTime to choose your battle specialization. Will you preserve your allies, or devastate your enemies? \n\nTo hone your combat skills to their sharpest, choose Devastation.\n\nTo maximize your healing potential, take the path of Preservation.\n\nTo enhance your wingmates, embrace Augmentation.\n\nEach specialization should serve you well. And remember, you can change or adapt it later.", completion = "Excellent choice.\n\nRemember, you can reconsider your specialization and adjust abilities as needed--so long as you are not in the heat of battle.", objectives = "Choose a specialization.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65702] = { id = 65702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Driven Mad", description = "The Azure Archives was once a place where the blue dragons would gather to discuss magic.\n\nNow I am the only one of my kind here.\n\nThis place controls the ley lines beneath the Azure Span, but it and its servants have gone out of control.\n\nI believe if we bring order to this place that I can then reclaim the Azure Oathstone.\n\nThe various constructs and elements are brimming with unstable arcane energy that needs to be redirected.\n\nDestroy them and collect what you can.", progress = "The archives are in a perpetual state of recreation for most of its guardians. We need to fix its flow.", completion = "Excellent work. The creations here are already being soothed with just this amount of unstable arcana removed.", objectives = "Recover 40 Unstable Arcane Energies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65703] = { id = 65703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
quests[65704] = { id = 65704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
quests[65705] = { id = 65705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands (60) E" }
quests[65709] = { id = 65709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Pruning", description = "We cannot activate the oathstone in the Azure Archives until we fix the issue with the out of control ley energy here.\n\nTwo out of the three draconic runes that are meant to control it are being choked by unstable arcana.\n\nI apologize that this falls to you, given Khadgar's responsibilities and the lack of my brethren appearing.\n\nThere should be a ley scepter within that bag of helpful goods you have.\n\nUse it to help repair the runes nearby.", progress = "The ley scepter should allow you to properly align and configure the runes nearby.", completion = "Excellent work. It seems these runes are able to transport us to the top of the archives.\n\nI believe that may be where our last problem resides...", objectives = "Look through the Bag of Helpful Goods for the Ley Scepter, then use it to repair 2 platforms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65711] = { id = 65711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Its Thunder", description = "It's you! Thank Ohn'ahra. I was pretending to be hurt to fool the next brute who dared come in here. Ugh--the hoof lickers put some binding spell on me. I'll figure it out.\n\nThey've got Lizi in the cave. Please save her. I'll figure out how to free myself.\n\nDo what you have to do.", progress = "Anyone whose laid a hoof on Lizi will pay!", completion = "<Radiya is unusually quiet and trembling slightly as she looks upon the tortured beast.>", objectives = "Kill the Storm Extractors and rescue Lizi the Thunderspine in Kaighan Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65717] = { id = 65717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading Motives", description = "<A small object catches your eye. It glitters with Progenitor magic--ancient, yet... strangely more refined.>\n\n<Soft vibrations and tones are woven into the device in a repeating refrain that almost seems to be trying to... speak?>\n\n<Firim would be very interested in this.>", completion = "By the First Ones... once again, you bring me the extraordinary. You say you found this when you defeated the Jailer? How curious.\n\nIt almost seems as if it's trying to... to communicate somehow. The implications alone are--ah! Forgive me for getting carried away. This will require more than simple research, I'm afraid. \n\nPlease, take this in return. It was one of my first discoveries--I suspect you have more to gain from its mobility than I do. \n\nThank you, my friend.", objectives = "Bring the Almanac's Echo to Firim in Exile's Hollow.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65725] = { id = 65725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "The large bufonid beneath the mud remains still.\n\nThere must be something it fancies. Have you some meats we can use to lure it out?", completion = "Thank you, {name}. Let us see if this does the trick." }
quests[65726] = { id = 65726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "If meat and honey could not lure this creature from the waters, let us try another approach. \n\nBring me some Shrouded Cloth. I will craft a net from it that may be more effective.", completion = "Thank you, {name}. Let us try this for Bud's sake, if not our own curiosity." }
quests[65727] = { id = 65727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", description = "Have you stopped to watch the bufonids?\n\nA lovely one lurks underwater. Still, patient, unmoving. Wise Bud takes after him. They are much alike. I sense Bud desires to see this large bufonid up close. \n\nPerhaps the creature can be lured out with some honey from the vespoids here in Zereth Mortis. Would you please gather some?", progress = "Have you found that honey?", completion = "Thank you, {name}. Now, let us see if this will entice that bufonid to emerge.", objectives = "Collect 15 Vespoid Honey from Vespoid around Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65728] = { id = 65728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "Since a trap did not work, let us try again to find a lure that interests this austere bufonid. \n\nPerhaps it desires some fish? Please bring us some.", completion = "Thank you, {name}. Let us hope this works." }
quests[65729] = { id = 65729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "I am running out of ideas. What else might entice our shy friend?\n\nLet us try more flesh from the creatures of Zereth Mortis. Something must grab its attention!", completion = "Thank you, {name}. Let us see if this produces results." }
quests[65730] = { id = 65730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "What else could we possibly try to persuade this bufonid to emerge?\n\nMaybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", completion = "Thank you, {name}. Maybe our bufonid friend just has more refined taste." }
quests[65731] = { id = 65731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burrowed Bufonid", progress = "Hmmmmm...\n\nMy friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis' supply of tempting flavors. \n\nI have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: \n\nSweet organic melons. \n\nMy dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", completion = "Thank you, {name}. This is a piece of a past long lost and forgotten...\n\nBut it is not for me. Let us see if this at last will attract our hidden bufonid friend." }
quests[65732] = { id = 65732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Patient Bufonid", description = "Look, another magnificent creature of Zereth Mortis! By the glint in its eye, I would say it was playing along the whole time.\n\nPatience delights. Bud is pleased. \n\nExcellent work, Maw Walker.", objectives = "Thank you, {name}. The creature seems quite friendly, and I believe it has taken a liking to you! I am certain you will take excellent care of it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65735] = { id = 65735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Custos", description = "A once-stable automa is showing signs of unusual dysfunction, attacking Enlightened along the road outside of Pilgrim's Grace. \n\nIt is essential that the roads remain safe for our pilgrims.\n\nRafiq has designated the elimination of this threat to be of the highest priority.", completion = "I do not understand why it was behaving in that manner, but we will be safer now that it is gone. This reward shall start you on the way towards some of my finer equipment.", objectives = "Eliminate Custos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65748] = { id = 65748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Supply the Effort", description = "The gear I provide is made available by the blessings of the First Ones and the... efforts of many other travelers.\n\nEach of us needs to provide for those that will follow later.\n\nCollect what provisions you come across in your exploration of Zereth Mortis. Keep a sharp eye out--they may be hidden in mysterious places. Return them here to me. I will in turn provide them to future travelers.", progress = "What have you found for me?", completion = "Well met, traveler! What have you found there? Ah, this will help many other travelers in need. You have my thanks--and theirs as well.", objectives = "Locate 10 Enlightened Provisions from chests, nests, relics and other containers about Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65749] = { id = 65749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Necessity Of Equipment", description = "I have been sharing research for some time with an associate of mine, Rafiq.  It is only through our shared efforts that he has been able to acquire useful items.\n\nDeliver my latest research notes to Rafiq and see if you can earn favor with him. In time, he should be able to aid you with better equipment.", progress = "What is this you have brought me?", completion = "You have my thanks {name}, and a gift for your future efforts.", objectives = "Collect Firim's Research Notes and deliver them to Rafiq.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65750] = { id = 65750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eight-Legged Menace", description = "{class}!\n\nI require your aid if you're willing...\n\nThis joint expedition was intended to study the unique arachnids inhabiting the area, but, as you can see, our plan has gone awry. \n\nWhat we originally assumed was an evolutionary adaptation is instead a Primalist perversion of the natural order!\n\nI take my responsibilities as a conservationist seriously, but the time for studying live specimens has passed. We can't let their perversion spread. We can study their corpses instead. \n\nWill you help us?", progress = "Is it done?", completion = "An unfortunate necessity. We could not allow them to spread.\n\nI think we've learned all we can from them.", objectives = "Kill 10 Shiverweb Creepers or Shiverweb Crawlers and 3 Primalist Tenders in Shiverweb Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65751] = { id = 65751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Platform Adjustments", description = "It seems the last of the arcane disruption is up here. \n\nI'll continue adjusting the ley energies. Use some of the arcana you recovered to dispel the disruptions here.", progress = "Do you need anything?", completion = "Fine work! I can feel the ley lines beneath this place beginning to heal. We're almost done.", objectives = "Dispel 3 Unstable Arcane Energies at the top of the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65752] = { id = 65752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Annoyances", description = "A large number of mana wyrms are absorbing the wild arcane magic coming out from the archives.\n\nThe rate that they're doing it is causing the ley lines to be thrown off balance... which is preventing the Azure Oathstone from being reclaimed.\n\nI will use some of the unstable arcana you collected to form a hook of sorts.\n\nUse it to slay several of the wyrms. The brief delay will be enough for me to adjust the energies below.", progress = "These wyrms will learn to feast somewhere else.", completion = "The Kirin Tor will ensure these archives are properly cared for when this is finished. Thank you for your aid.", objectives = "Slay 6 Feasting Wyrms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65758] = { id = 65758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grungir the Explorer", description = "{name}! My Explorers' League counterpart, Grungir Ironspout, wasn't among those you rescued. He had fought his way free originally, but once he saw how few of us made it out, he turned around and headed right back in! Alone!\n\nThe oaf is as brave as he is impulsive and does not deserve whatever fate has befallen him.\n\nPlease... find him.", completion = "Good tae see another face with the right number o' eyes!", objectives = "Find Grungir Ironspout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65760] = { id = 65760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting for Duty", description = "I've only read of the djaradin in books.\n\nAncient rivals to the dragons, powerful giants with mastery over earth and lava... dedicated wholly to hunting dragons to extinction.\n\n<Sendrax furrows her brow at the distant volcano.>\n\nMy instructor said that they hadn't been seen since the dragons left as they slumbered deep in the earth.\n\nIf they've awoken, every whelpling on the isles is in danger!\n\nWe should hurry to Commander Lethanak at the Dragonheart Outpost.", progress = "Our ancient enemies have risen from their slumber... and wasted no time.", completion = "I will take what reinforcements I can get.\n\nWe must act swiftly.", objectives = "Meet commander Lethanak at the Dragonheart Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65761] = { id = 65761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Adventure Than Expected", description = "<Godoloto's stare is beady and accusatory. She huffs.>\n\n<Perhaps the ohuna can help you find and rescue Radiya.>", completion = "{name}!", objectives = "Work with Godoloto to find and rescue Radiya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65762] = { id = 65762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Mythic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65763] = { id = 65763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Heroic Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65764] = { id = 65764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65768] = { id = 65768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Forward Scouts", description = "The Jailer's forces control much of Zereth Mortis, but there are other dangers out there as well.\n\nI have dispatched scouts to survey the surrounding area and pinpoint any potential threats.\n\nSpeak with each scout. They should have a report of their surveys. Gather this information and then return to me.", progress = "What have you discovered?", completion = "This information will help us plan our next move. Thank you, Maw Walker.", objectives = "Speak with the forward scouts in Zereth Mortis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65769] = { id = 65769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icy Webs", description = "Many of my friends and colleagues were captured when the arachnids and their Primalist masters attacked. \n\nI saw them being bound in frozen webbing and dragged away to a fate I dare not consider. \n\nPlease free any of them that you can!", completion = "Thank you, {name}. I feared I would never see any of them again.", objectives = "Free 6 Cocooned Survivors in Shiverweb Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65770] = { id = 65770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Promise Is A Promise", description = "The animals are comfortable around you. That's a good indicator of your spirit.\n\nActually... can you keep a secret? I want to introduce you to my friend. Nobody else knows about her.\n\nYou have to promise me first that you'll keep this between us. My Ohn would exile me from the plains if she found out.", completion = "<Togotseng's ohuna glares at you.>", objectives = "Promise Initiate Radiya to keep her secret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65771] = { id = 65771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor of the First Ones", description = "The attack from the Jailer's forces is a sign! In the past, there was one among us who sought the forbidden knowledge of the First Ones. For that, we must have earned their ire and lost the protections we once had.\n\nWe must atone for the trespasses of our kin.\n\nTake this incense. Go out into the veldt and burn it as offerings to the First Ones. I hope they will offer us forgiveness.", completion = "May the First Ones accept these offerings as penitence for past transgressions. \n\nThank you, Maw Walker.", objectives = "Burn Enlightened Incense around the Great Veldt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65772] = { id = 65772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Harvest", description = "Between the Mawsworn attacks and your presence here, our supplies are dwindling. It pains me to say it, but the most immediate solution for replenishing our resources is the local wildlife. \n\nIt is unfortunate that it has come to this, but it is what must be done. Cull some of the local wildlife, and help us replenish our supplies.", progress = "Have you brought us the necessary supplies?", completion = "Thank you. Your efforts are greatly appreciated.", objectives = "Collect 15 Latent Protein from raptora, cervids, and lupines in The Great Veldt and surrounding area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65773] = { id = 65773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solo Mission", description = "Seems it is time you prove yourself alone.\n\nThere's a chance for continual conflict, but this has to be undertaken by yourself. Sometimes you have to fight along side enemies to understand their tactics, this seems like a chance.\n\nGood luck.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing.", objectives = "Complete 5 rounds of Solo Shuffle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65774] = { id = 65774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Catalyst Awakens", description = "Adventurer, can you feel it? High above the Catalyst Gardens, the Creation Catalyst hums with new power. \n\nThis power will change the world itself. You must harness it at once.", progress = "The very fabric of creation shudders.", completion = "The power of creation itself is in your hands.", objectives = "Travel to the Catalyst Gardens and use the Creation Catalyst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65775] = { id = 65775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soloing Strategy", description = "You survived that battle test.\n\nI still think improvements can be found during these bouts. Try again.\n\nReturn when you are finished.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing.", objectives = "Complete 15 rounds of Solo Shuffle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65777] = { id = 65777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mudcaked Necklace", description = "<The ancient markings on the necklace are quite difficult to read, but the materials appear to be made of animal hide and carved bone fragments.\n\nPerhaps a knowledgeable hunter may glean insight into this object's value.>", objectives = "Locate someone knowledgeable in plainshunting and handcrafted artifacts.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65778] = { id = 65778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Screechflight Potluck", description = "Are you ready to put those acting chops of yours to good use, {name}?\n\nWhat? You don't have any chops? Then it's a good thing I've made you an im-PECK-able Screechflight disguise out of all the materials you just gathered!\n\nSegallia and I still need time to finish building the final \"egg\" that will take out the matriarch, but I've made a smaller, prototype version for you to try out on the chef.\n\nAnd don't worry! You'll be 12% safer from these explosions under all the feathers!", progress = "Old Monte Gazlowe once invited me over and cooked dinner to impress me. To be honest, it smelled a lot like whatever is coming from that cave over there.", completion = "You did great and looked pretty good in that outfit to boot!\n\nFinally ready to cut this terrifying threat off at its beak?", objectives = "Wear your disguise and use the Prototype \"Egg\" on the Matriarch's Personal Chef.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65779] = { id = 65779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Plains", description = "The green dragonflight has returned to their gardens in the nearby plains. Queen Alexstrasza wishes for you to make contact with Merithra of the Dream.\n\nThe centaur of those plains are fierce hunters. To reach the Emerald Gardens, you will need to establish diplomacy with them first.\n\nBe respectful, but show no weakness.", progress = "<Tomul eyes you up and down with reserved curiosity.>\n\nState your business in the plains.", completion = "You serve as an envoy of the dragons, then. Times are changing.", objectives = "Meet the Shikaar scout in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65780] = { id = 65780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Oneself", description = "A gift from dragons may impress some centaur, but Clan Shikaar must see how well you hunt.\n\nOne of our hunting parties just brought down a proto-dragon infused with the power of flame. Prove your worth by aiding in the kill.", progress = "You look like you can handle yourself, but looks can be deceiving.", completion = "You are a more formidable fighter than I assumed.", objectives = "Slay the Blazing Proto-Dragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65782] = { id = 65782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Lock and Key", description = "When we heard rumors of a Deathwing cult, Majordomo Selistra ordered me to bring these erstwhile scaleborn back into the fold. We'd hoped it was a simple misunderstanding.\n\nClearly, we were wrong.\n\nTheir leader must be dealt with--but first I need out of this cage. Find the key and bring it to me.", progress = "I must admit: this cage has gotten rather tiresome.", completion = "I may have suffered imprisonment--but the Worldbreakers barely spit an ember next to the Twilight's Hammer. I should be grateful for that at least.", objectives = "Acquire the Worldbreaker Cell Key and free Ayasanth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65783] = { id = 65783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome at Our Fire", description = "You have fought alongside our hunters and earned a place at our fire.\n\nOur khan is at our hunting post in the swamp, readying our upcoming caravan. I will notify her of your arrival and purpose.\n\nSurely you can find your way on your own.", completion = "You outsiders seem to have a habit of meddling in the affairs of others.", objectives = "Meet with Scout Tomul at Timberstep Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65784] = { id = 65784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Otter Side", description = "To the northeast, there are a system of otter burrows along the bank. Some of the otters there are blessed by the river to grow to magnificent sizes.\n\nI will not have you hunting these blessings out of respect. Instead you will bring them back here, alive, so that we may treat them with the reverence they deserve.", progress = "Remember, they must be returned alive.", completion = "Fine creatures. We will make use of everything they have to offer.", objectives = "Bring 3 Gargantuan River Otters back to Clan Aylaag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65788] = { id = 65788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Walk with Ghosts", description = "Reclaiming these ruins means a lot to the Forsaken. Especially since the war ended, our people have needed something to hold onto, to give us purpose in the wake of everything that's happened to us.\n\nI saw Calia walk toward the throne room. That place holds many memories for her. Many ghosts. \n\nWe should check on her.", completion = "Thank you, {name}. You have helped so much. \n\nFrom here, I believe the Forsaken will rebuild and solidify their identity. Not just as former denizens of Lordaeron, but as their own people. A people I am proud to be one of.", objectives = "Speak to Calia in the throne room of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65789] = { id = 65789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Rivers Sleep", description = "The Mirewood contains key reagents often used to converse with the ancestors. Unfortunately, the Mudfin tribe swarms the area, making it difficult for us to forage the area.\n\nIf you could gather some of the blooms within the marsh, along with some of the Mudfin's own resources, I would appreciate it.", progress = "Have you found everything?", completion = "I thank you. These will be put to good use.", objectives = "Collect reagents from Mirewood Fen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65791] = { id = 65791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life-Binder on Duty", description = "Soon the Life Pools will be full once again.\n\nThank you for your part in this, {name}, it means more than I can ever hope to express.\n\nGo, find the Life-Binder by the oathstone. Tell her that we are ready for the eggs.", completion = "The future of all the flights is now secure.", objectives = "Meet Alexstrasza by the Ruby Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65792] = { id = 65792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeth for a Tooth", description = "Toliqui has been claiming that just the other day she killed a rockfang without any assistance. Given our connected souls, I don't want to call her as a liar. So instead... \n\nI want to prove to her, and everyone else, that I'm the better half of our soul! The nearest rockfang quest is to the northeast - meet me there!", progress = "I cannot let Toliqui continue to leave me in her shadow.", completion = "The clan will be talking about this for weeks!", objectives = "Slay 10 rockfangs with Toluijin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65793] = { id = 65793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Wagon Flight", description = "With the oathstone empowered once more, we must now transport the future of our kind to the Life Pools. It is the right of every true dragonflight to have their eggs nurtured by its waters.\n\nUnfortunately, our enemies will be watching the skies, now that we have revealed ourselves. We will make the final leg of the journey on foot to avoid their scrutiny.\n\nMeet me near the Obsidian Bulwark, {class}. As the Life-Binder's champion, you are welcome to join me in this.", completion = "You have served admirably, {race}.", objectives = "Escort the eggs to the Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65794] = { id = 65794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charge of Care", description = "You have my thanks, {class}, and my condolences for having to deal with those two for as long as you did.\n\nThe red dragonflight is charged with the preservation and nurturing of all dragons, even those we may tire of at times.\n\nWith the return of the Black Dragonflight's eggs, dragonkind is united as it has not been in thousands of years. I believe this is what will restore our ruby oathstone.\n\nSpeak with me when you are ready to bring the eggs to the Obsidian Lifepool.", completion = "The Life Pools are filled once more, in no small part thanks to you.\n\nWith our purpose fulfilled, our oathstone shines once more as a symbol of our calling.", objectives = "Witness the Black Dragon Eggs rejoin the Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65795] = { id = 65795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next Steppes", description = "The green dragonflight requires your aid now, hero. My sister's daughter and her flight have entered the Emerald Dream in an attempt to empower their own oathstone, but we have heard nothing since their slumber began.\n\nSeek out the centaur that rule over the Ohn'ahran Plains. You may well need their connection to the land and its spirits if you are to rouse the greens.\n\nThey are a proud and territorial people who do not suffer insult lightly. Speak with our ambassador and he will prepare you.", completion = "We have much to discuss, you and I.", objectives = "Meet Ambassador Taurasza in the Rubyscale Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65796] = { id = 65796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Defense...", description = "Our next path is through Nokhud territory. Historically, we have been at a tentative peace with their clan, but times have changed. \n\nIf we do not act first, we leave ourselves open while we're vulnerable. My scouts have reported that one of their war leaders has been spotted near Dragonsmeet. Take the fight to her directly - do not let her gather the forces to assault us on the move.", progress = "I cannot afford any mistakes. There are too many lives counting on me.", completion = "Thank you, this will give me some peace of mind as we prepare for our journey.", objectives = "Slay Sirena the Fangbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65798] = { id = 65798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportunistic Approach", description = "The Shikaar have formed an offensive line against the Nokhud to the north. While I do not like stooping to scavenging, it is unfortunately a necessary evil for our supplies. Brave the battlefield and return with weapons, and I will reward your efforts.\n\nIf you could focus said efforts on the Nokhud side of the line, perhaps the ancestors will judge me less harshly.", progress = "Weapons will be the most useful thing - I apologize for asking this of you.", completion = "Ancestors forgive me. If I were stronger, we would not need to resort to such a questionable method for resources.", objectives = "Retrieve weapons and slay Nokhud forces at the Nokhud Approach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65801] = { id = 65801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Introductions", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nIt has been countless generations since an outsider like you reached our lands. With Primalists treading on our lands and peddling forbidden magics, my people are understandably wary.\n\nIf you are to travel with us, you must make yourself known. Introduce yourself to the members of my clan.", progress = "Good. The Khan is putting you to work.", completion = "The rest of our attending clan has already traveled to Maruukai to prepare our site. The caravan from this outpost will be the last to arrive.", objectives = "Introduce yourself to members of Clan Shikaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65802] = { id = 65802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies for the Journey", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nWhile you travel with us, you must pull your weight. Unruly gorlocs have been raiding our medical supplies recently, and we must restock. Gather the orange blooms around the outpost so we can create more poultices.\n\nThere are supplies around the outpost that need to be brought to the caravan as well. I would like you to gather them while you are out.\n\nOnce you have everything, bring it to Tomul.", progress = "Don't bother me until you have the caravan provisions.", completion = "<Scout Tomul looks over the gathered provisions.>\n\nEverything seems to be in order.", objectives = "Collect 5 Camp Provisions from around Timberstep Outpost and 4 Feralbloom Pods from the nearby woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65803] = { id = 65803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toward the City", description = "The Khural is a time of discussion amongst clans. Stories are shared. While there are many centaur clans across the plains, we are all Maruuk.\n\nThe caravan is ready to go. As Maruukai is some distance away, we will make stops.\n\nWhen you are ready to leave, find me at the caravan. Don't keep us waiting.", completion = "Take a breath, two-foot.", objectives = "Travel alongside the Shikaar caravan to Wanderer's Steppe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65804] = { id = 65804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Food and Rivalry", description = "Maruuk travel from all across the plains to attend the Khural, and the gathering lasts many days.\n\nFeeding that many centaur is no simple feat. Clan Shikaar's hunters provide meat for all of the shared meals. It is our tradition to hunt on our way to Maruukai. \n\nYou must pull your weight as well.", progress = "Our youngest hunters are passionate and determined. Be sure they don't show you up.", completion = "You hunt as strangely as you fight. I hope Aru and Belika observed your technique.", objectives = "Collect 30 Fresh Game Meat from wildlife in Wanderer's Steppe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65805] = { id = 65805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Connection to Ohn'ahra", description = "The wind is restless here, {name}. Ohn'ahra is reaching out. I must answer her call.\n\nI need reagents for my ritual: reeds from the riverbanks, feathers from the tails of mallards, and the heart of a salamanther. Gather these materials from the river so that I may heed her voice.", progress = "Ohn'ahra's song is fleeting. We must work quickly.", completion = "Excellent. I will use these materials to interpret her song.", objectives = "Collect 4 River Reeds, 8 Fowl Tailfeathers, and a Salamanther Heart from the river banks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65806] = { id = 65806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruukai", description = "<Okir vocalizes as Sansok Khan signs.>\n\nMaruukai rests beside a mountain near this grove. Our journey is almost over.\n\nThe Khural is a time of truce amongst the Maruuk, but Ohn Seshteng's omen is troubling. We must stay on our guard.", completion = "Welcome to Maruukai.", objectives = "Travel into Maruukai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65832] = { id = 65832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Antifreeze", progress = "I can feel ma wee piggies freezin'!", completion = "Thank Magni! This'll keep me blood from freezin' long enough for the ice tae melt.", objectives = "Find 6 Flasks of Dwarven Antifreeze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65833] = { id = 65833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primalist Tampering", description = "The Primalists are infusin' spiders with elemental ice and are fixin' to use 'em as shock troops tae overrun the dragons' defenses in the Span. We cannae let that happen.\n\nThe three frosty lookin' ones are in charge. Take 'em out and bring me the runestones they're using tae focus the primal magic and we can see about cuttin' off the flow.", progress = "Did ye get all three?", completion = "Serves 'em right.\n\nThank ye, {name}.", objectives = "Retrieve the three Frostcallers' Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65834] = { id = 65834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Queen", description = "Here we go! A lil' formal education, a lil' educated guessin', a touch o' re-chiselin' runes, and we got ourselves a magic un-infuser! Defuser? Out-fuser?\n\nWhatever! It'll do somethin' unpleasant tae the queen, o' that I'm pretty sure. And she's got tae go if we're aimin' tae stop the threat. Squashin' the lil' ones will only slow 'em down. Ye got tae cut 'em off at the source.", progress = "She's in the cave over yonder.  Giant spider. Cannae miss 'er.", completion = "Aye, that should throw a wrench intae their plan.\n\nNow... just tae push... a... lil'... harder...", objectives = "Slay the Shiverweb Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65836] = { id = 65836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show of Storm", description = "<Watu stands up easily, as if his injury was gone.>\n\nI--I--I stuck the shard into myself. Nothing hurts anymore. I feel good. Great. Immense.\n\nOlekk still isn't back. Something must have gone awry. He should have never gone without me!", completion = "No!", objectives = "Regroup with Watu in the Sagecrest Pines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65837] = { id = 65837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble In The Pines", completion = "Tirren? He's still hoofing around, is he?\n\nThank you for coming. We can use all the help we can get.", objectives = "Speak to Sentinel Olekk at Pinewood Post in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65838] = { id = 65838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Brackenhide", description = "If the gnolls here have discovered decay magic, the ley line and even the land itself are in grave danger. \n\nMy mirror images are spread too thin to withstand elemental disruption of this scale. Please enter the forest and investigate the decay. \n\nI'll work with our new tuskarr friends to find a place I can maintain my image. Then, I will meet you deeper in the forest.\n\nWe must put a stop to this!", progress = "Can you sense the disruption of magic all around us?", completion = "You may want to cover your mouth. You don't want to breathe in the decay.", objectives = "Investigate Brackenhide Outskirts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65840] = { id = 65840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future.", objectives = "Eliminate Doventhal the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65841] = { id = 65841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Spread" }
quests[65842] = { id = 65842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Behavior", description = "I have little love for the Worldbeaker dragonkin. They follow a misplaced belief that Deathwing himself will return one day, and they will not help us with the Obsidian Throne.\n\nWeaponmaster Vordak, who once swore loyalty to the Black Prince, has stolen many weapons crafted here in the Citadel and given them to the Worldbreakers. I will not allow such theft. Or such betrayal.\n\nGo to Smoldering Peak and recover the weapons... by force if necessary.", progress = "Have you acquired the weapons?", completion = "Well done. These weapons are back where they belong.\n\nI'm sure this won't be the last conflict we have with the Worldbreakers, either. Anyone crazy enough to think that Deathwing will return isn't going to be reasoned with.", objectives = "Eliminate Weaponmaster Vordak and collect 15 Worldbreaker Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65844] = { id = 65844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Out the Rot", description = "This decay must have rotted these gnolls' brains as well as their bodies! \n\nDestructive as they are, gnolls are native to this land--just like us.\n\nBut we already saw them spreading decay to the Big Tree Tribe. At this rate, they'll consume the Span and destroy themselves. \n\nWe can't let this happen. It's a shame... but put an end to them.", progress = "Er, please, do tell... Did you see any interesting effects of the decay on any gnolls you observed? The effect on their social structure must be enormous...\n\nAh, we should stay on task.", completion = "Gnolls can be fascinating creatures! They're not evil, only wild. And very dumb. \n\nKilling them is a shame, but the decay helps no one. And we can't let them hurt our family.", objectives = "Kill 5 Rotting Treants and 10 Brackenhide Rotflingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65845] = { id = 65845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of the Fallen", description = "There are tuskarr here! My friends, my people--my family. They left for a hunt not a week ago.\n\nAlready they're too decayed to recover. \n\nTheir spirits are here still. They linger in rage and regret. Kaqiata, Lutokk, Tuyuki...\n\nPlease, {name}, take this totem and place it near their remains. It'll contact their spirits... and help them find peace.", progress = "Some of my fallen kin were able to take Karkut's hand into the next world. Others weren't. I feel their presence like a weight.\n\nLutokk was going to wed in the next moon. \n\nTuyuki wanted to sail to Northrend to reconnect with our distant kin. \n\nPopoak was a great hunter, and Hanu's cousin. His kills made for the best soups.\n\nNomurok was so young. This was his first hunt.\n\nKaqiata was little Rowie's only blood family left. Now who'll teach him to fish?", completion = "So they all chose to lend their power to my totem? \n\n<Brena squeezes her eyes shut in sorrow.> \n\nThank you, my friends. We will use the strength of your spirits well. The gnolls will not reach Iskaara.", objectives = "Place Brena's Totem near 5 tuskarr corpses to contact their spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65846] = { id = 65846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Litter", description = "The ley line is here--I can feel it! \n\nBut first, we must stop the gnolls. That ancient will be their greatest weapon.\n\nThere are some ley crystals the gnolls have gathered. Thankfully, they don't seem to understand the power that the crystals hold. \n\nBring me as many as you can. They'll empower my mirror image and help me summon something useful from the Archives to take that monster down!", progress = "I'm sorry I can't be of more help in this form. I can feel the decay sapping my image's strength. \n\nI hope once we reach the ley cavern, Gleamcove as the tuskarr call it, I'll be able to teleport here fully.", completion = "What were they doing with these? Using them as back scratchers?!\n\n<Kalecgos pinches the bridge of his nose.>\n\n...I suppose we should be grateful they didn't figure out their true potential.", objectives = "Collect 7 Ley Crystals from Brackenhide Outskirts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65847] = { id = 65847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Realignment", description = "Now for this ley line. It looks like my fears were correct -- the decay has spread into the line itself.\n\nWe'll need to purge the decay and speed along the healing process, but I can't channel enough energy with my mirror image alone. \n\nFocus yourself on this ley crystal here. My connection with you will help me teleport here physically. Then, I will be strong enough.", progress = "While the decay here is lessened, it's still thick enough to cause trouble teleporting safely.", completion = "We did it. Great work, {name}. Breathe the fresh air again!\n\nWith this ley line restored, and Khadgar finishing up on the one in the tower, the Oathstone should be ready to claim. I must return to the Azure Archives shortly.", objectives = "Focus on the Ley Crystal, then destroy 3 Decay Infections.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65848] = { id = 65848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome-ward Bound", description = "We must stop that tree! With these ley crystals, I can finally help.\n\nSpeak with me when you are ready. I'll open a portal into the Azure Archives and try to bring out something useful. \n\nStand back, it may be rather unstable.", progress = "This should be interesting!", completion = "You did well, hero, thank you. \n\nThat tree was probably not their only pool of decay, but it was the riskiest one for the tuskarr and this ley line. With it gone, this area may be able to recover. It will take time, but it will heal. \n\nI'm glad we were able to give the spirits of those tuskarr some peace.", objectives = "Speak with Kalecgos to open the portal, then use what he summons to take out the Brackenhide Putrifiers and then destroy the Twisted Ancient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65849] = { id = 65849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Iskaara", description = "Thank you, {name}, for all your help. My family is safe because of you.\n\nNow, we can finally return to Iskaara and see old Ponoliak taken back to the sea. He was my mentor, and a fine chieftain. \n\nPlease, you must join us! A celebration of the Cycle of the Sea is something all can share in.", completion = "I'm so glad you have come to join us. \n\nI must ask you to be patient, however. There is still much to be prepared for the ceremony.", objectives = "Meet Brena in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65850] = { id = 65850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of the Sea", description = "Thank you, {name}. I have learned what I need for now from our new friends. \n\nThe funeral ceremony for their former chieftain is about to start. Given how kind and hospitable the Iskaarans have been to us, it seems only right that we join them before departing back to the Archives. \n\nSpeak with Brena and let her know we are ready when they are.", progress = "It is good to slow down, now and then. And interesting to see the tuskarr's traditions. \n\nIt has been long since the blue dragonflight has had traditions such as these.", completion = "<Kalecgos looks distant.>", objectives = "Speak with Brena to witness the funeral ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65852] = { id = 65852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straight to the Top", description = "There appears to be something sapping the arcane energies at the apex of the tower. \n\nNow that you've stabilized the energies down here, you should be able to \"ride\" the arcane magics in the area.\n\nLook in that bag of yours for something called an arcane stepping stone, and use it to meet me at the top.", progress = "It's a long way down from here. Be careful.", completion = "It's a bit worse up here than I had anticipated!", objectives = "Look through the Bag of Helpful Goods for the Arcane Stepping Stone, then use at an arcane focus point to reach the top of the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65854] = { id = 65854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Oathstone", description = "Fine work, friend. It seems we've managed to repair the leylines within the Azure Archives.\n\nBack when the blue dragonflight was united, I would tell my brothers and sisters to never doubt the strength of mortals.\n\nMeet me at the oathstone to the south of here. I will reclaim it, and then be on my way to Thaldraszus.", completion = "It is good to be back... or reactivated, as it were. \n\nThere is much to do, and I am glad to give whatever aid I can.", objectives = "Witness Kalecgos reclaim the Azure Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65855] = { id = 65855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding Azure Span", description = "The oathstone's energy cannot be reclaimed until the ley lines within the Azure Span are repaired.\n\nSome ley lines may only be reachable by those of Kalecgos's skills... but you may still be of aid.\n\nIf they still yet survive, seek out the tuskarr. They lived here in my times and have a deep knowledge of the land.\n\nSpeak with one of our arcane aids to return to your allies.", progress = "What can I do for you?", completion = "The tuskarr? There are a number of tuskarr merchants and travellers who pass through here.", objectives = "Return to Noriko the All-Remembering in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65864] = { id = 65864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Caravan", description = "You should catch up with Brena. Her caravan passed through no more than a few hours ago.\n\nThey were collecting our late chieftain's most prized possessions for a funeral to honor him.\n\nGiven that the caravan was heavily burdened, she can't be far ahead.", progress = "I've got you, Hanu.", completion = "The gnolls were ruthless in their assault.\n\nThey hit us hard and fast and took everything that wasn't nailed down.", objectives = "Catch up with Brena near the Big Tree Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65865] = { id = 65865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They've Got Us Pinned Down!", description = "These gnoll sharpshooters are ruthless... and surprisingly accurate.\n\nWe cannot even consider heading into the Big Tree Hills while they have their weapons trained on us.\n\nThin our their ranks and show them that we will not be used for target practice!", objectives = "Kill Gnoll Sharpshooters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65866] = { id = 65866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap the Traps", description = "The hills ahead are littered with insidious bladejaw traps.\n\nWith a keen eye, you should be able to locate them. Very carefully spring the traps using this old tuskarr trick: a long stick. Note that while stepping on them is another way to set the traps off, I wouldn't recommend it.\n\nOnce enough have been removed, find Hanu. Elder Poa and I will catch up when we can.", completion = "Well done. It will be safer for Brena to make her way here.", objectives = "Spring 5 Bladejaw Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65867] = { id = 65867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling in the Big Tree Hills", description = "The gnolls that attacked our caravan were led by three lieutenants.\n\nDurgun was flanked by a dozen hyenas.\n\nKerwal cackled maniacally each time we tried to pursue him and fell for one of his steel-jawed traps.\n\nBakra taunted us, mercilessly.\n\nTo have a hope in recovering what was stolen, they must be slain.", progress = "<Hanu stares at you intently.>", completion = "Good, you did what I could not. \n\nBut there is another gnoll leading the Shadepaw... more terrifying than the three you encountered.", objectives = "Slay Durgun, Kerwal, and Bakra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65868] = { id = 65868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't for Chewing", description = "I found one of Ponoliak's funerary offerings, mishandled and then discarded by these Shadepaw gnolls... It has bite marks all over it!\n\nThis offering, and others like it, are needed for the memorial ceremony for the recently deceased Iskaara chieftain.\n\nIt's a travesty that something so sacred should be employed as a chew toy. Please keep an eye out for more offerings.", progress = "<Hanu leans forward and gazes into your pack hopefully.>", completion = "<Hanu's nose crinkles.>\n\nUgh... slathered in slobber.\n\nThey will have to suffice for the chieftain's memorial.", objectives = "Recover 8 Funerary Offerings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65869] = { id = 65869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Ambush", description = "A tragedy. And potentially the first of many more.\n\nFind out what Akiun knows, then examine anyone who fell in the attack. \n\nI have my hunches about what happened here. Let's see if the clues support my theory.\n\nMeanwhile, I'll try to reassure my rattled friends.", progress = "We must pinpoint the source of this gnoll aggression, before they can do any more damage.", completion = "This is truly a tragedy... but at least we can follow the clues.\n\nWe are getting closer to the source of this rot.", objectives = "Speak to Akiun and examine 4 nearby corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65870] = { id = 65870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies!", description = "There was no sign of our stolen hunting supplies in the Big Tree Hills. They must be in that cave.\n\nKeep an eye out for the supply containers, and be prepared for anything.\n\nI would not trust the gnolls to leave the goods unprotected.", progress = "I'd hate for Iskaara to go hungry...", completion = "<Elder Poa looks approvingly at the supplies you've recovered.>\n\nThe Iskaara tuskarr will hunt again.", objectives = "Recover the caches of hunting supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65871] = { id = 65871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnoll Way Out", description = "I've tracked the captured tuskarr, including my husband Norukk, to this cave. \n\nNorukk doesn't always look out for his own hide, so that responsibility falls to me. But I'm not too proud to ask for help.\n\nPlease rescue them!", progress = "We can't leave our brothers and sisters behind!", completion = "<Hanu wrinkles her cheeks and shoots a tusky grin at Norukk.>\n\nI'm beyond relieved that Norukk made it out alive. We will mourn those we lost once we return to Iskaara.", objectives = "Rescue Norukk and 3 other captive tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65872] = { id = 65872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill Gnolls with Ill Intent", description = "I'm catching a strange scent on the wind. Something here isn't right...\n\nHanu described the gnolls in this cave as strange... and sickly. We should learn more about what is causing this.\n\nDon't let your guard down. Despite their sickly appearance, expect them to be just as devious and dangerous.", completion = "We have never seen rot take on a form like this.\n\nThis is troubling.", objectives = "Kill 16 Shadepaw gnolls in Kargpaw's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65873] = { id = 65873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Shadepaw Pack", description = "Kargpaw is the true leader of the gnolls in this part of the forest. We've had... unpleasant encounters with him in the past.\n\nThis time was different. He carried a strange totem that seemed to twist his very essence.\n\nKargpaw must be stopped and this totem recovered. I fear the gnolls are meddling in something darker than we can imagine.", progress = "Did you recover Kargpaw's totem?", completion = "<Brena recoils in disgust as she accepts the totem.>\n\nKargpaw was always violent, but he was also a coward. He and his band never attacked us if we traveled in large numbers.\n\nSomething has changed... and this totem is behind it.", objectives = "Kill Kargpaw and recover his totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65874] = { id = 65874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rotten Revelation", description = "Hmm...\n\n<Brel peers intently at the strange totem, turning it over in her thick hands.>\n\nWe've got to put our whiskers together and determine what this means.", objectives = "Speak with Hanu, Elder Poa, and Norukk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65875] = { id = 65875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dragon's Day Off", description = "A lifetime spent in Outland... always fighting. So little time to relax!\n\nSometimes a dragon just needs a day off by the sea with a cold, cold drink in their claws.\n\nHey, maybe you can help me relax! Do me a favor and see if you can find a few of these drinks to refresh our supply here.", progress = "Have fetched my beverages yet? No? That's too bad.", completion = "Yes! Time to kick back and relax!", objectives = "Locate the various drinks for Vazallia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65886] = { id = 65886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Rhonin's Shield", description = "Raszageth and the Primalists are launching an all out assault on Vakthros. We cannot let her succeed!\n\nKhadgar and I will go ahead to handle the situation there from the sky.\n\nIn the meantime, make your way to the Rhonin's Shield, one of the last Kirin Tor camps in the area.\n\nYou may be able to get there faster by riding that drake of yours from the top of the archives.\n\nSee that the Kirin Tor there are all right, then make your way to Vakthros.\n\nWe'll be counting on your help from the ground.", completion = "I saw Kalecgos and Khadgar go towards the mountains a moment ago. We're holding our own against the Primalists here, but we can always use more help!", objectives = "Meet with Drok Scrollstabber in the Tower Outlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65887] = { id = 65887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Mountain", description = "It's a sight to behold up there, Khadgar and Kalecgos fighting the Primalists in the sky!\n\nThey've summoned several mirror images of themselves to help you through the monstrous hole the Primalists have created.\n\nOne pair is at the base of the mountains right now. \n\nIf things start to look bad... well I'll get the word out to the rest of us in the Azure Span.", completion = "This is worse than I could have expected. There's no time to lose.", objectives = "Meet Khadgar and Kalecgos's mirror images at the base of Vakthros Range.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65890] = { id = 65890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nelthazan Ruins", description = "The Dragonscale Expedition requires your assistance.\n\nA skyscribe was sent to the ruins to gather information. They should be uninhabited, but I can hear his shouting from over here.\n\nHe must be in dire circumstances for it to be audible at this distance.\n\nOn this expedition, we take care of our own. Even the insufferable ones. Seek him out and protect him from whatever danger he has found.", completion = "Well of course I am shouting! The book will not listen. What else am I to do?", objectives = "Meet Skyscribe Adenedal at the Nelthazan Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65891] = { id = 65891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Tirade", description = "Good. I was just thinking that I am in need of an adventurer like you. Strong. Sturdy. Willing to work for a trivial sum.\n\nIt is as if I willed you into existence. Well done, me. These ruins seem to have brought the attention of others. We cannot rely on them to excavate it properly. They will taint the samples!\n\nTake this. Deploy it around artifacts of interest around the ruins. It is enchanted to perform any necessary duty.", progress = "I think I shall write a bit of poetry. Or, rather, instruct the book to write it for me.", completion = "We will gather everything in time.", objectives = "Deploy the enchanted tools to 5 piles of rubble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65892] = { id = 65892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sundered Asunder" }
quests[65893] = { id = 65893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Relic Inquiry", description = "The Sundered Flame are here. Would you trust anyone claiming to be sundered with precious artifacts?\n\nI did not think so. Regardless, we need to know what they are here for if we are to proceed. Gather what you can recover from them and report back to me with your findings.\n\nThere are more pieces to this puzzle than what we will find in the ground.", progress = "These ruins are ruined enough.", completion = "They are still looking for something? Then why did you bring me this garbage?\n\nWe have to find it before they do!", objectives = "Gather 60 Nelthazan Artifact Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65895] = { id = 65895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competing Company", description = "Bah! We will learn nothing from the slaughter of laborers.\n\nSeek out their leaders. One of them will know what we need.\n\nOh, and {name}. Listen to them before you kill them this time. You may learn something useful.", progress = "What have you learned?", completion = "I have seen a sickness like this once before in my life. I had hoped to never see it again.", objectives = "Gather information about the Sundered Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65896] = { id = 65896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Healing Begin", description = "Do you think you would be able to step into this city without me noticing? No!\n\nI was right about your kind before and I'll be damned before I let dragons destroy my home again.\n\nThis once was a park filled with joy and peace. Then your progenitor, Deathwing, came. Oh yes, I know all about him. \n\nSee for yourself the legacy of destruction that was left behind. The pain that walks these streets still.", completion = "You have given me the most wonderful gift today. You have shown me that my city is ready to heal. That our legacies are still in our control.\n\nGo forth with honor, friend.", objectives = "Help the people of Stormwind heal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65898] = { id = 65898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proto Problems", progress = "I am glad you made it out safely. Do you have the Locus?", completion = "Thank you, {name}.\n\nYou have been most helpful.", objectives = "Acquire the Locus and defeat the protodrake that protects it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65899] = { id = 65899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Theramus", description = "{race}! Are you here to visit the beautiful Lilac Ramble? I'm so sorry about its current state. I promise it's not usually this untended!\n\nTheramus, the garden's keeper, was supposed to meet us today and tackle the issues together. He's been struggling with the upkeep lately, so Felina and I are helping out. But we can't do it all.\n\nWould you help us look around for him? Maybe he did forget.", completion = "You found him! It looks like he's really down in the dumps today.", objectives = "Search the nearby caves and find Theramus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65900] = { id = 65900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspiciously Spiced Steak", description = "My sister's idea is charming, but Theramus needs a real pick-me-up.\n\nThat would be a generous serving of sourbloom. We can make it into a paste to slather onto his favorite food: turtle meat!\n\nWill you help me collect the ingredients?", progress = "Do you know why sourbloom grow under the coastal trees?\n\nThe tree roots trap an abundance of nutrients from the waves, which then feed the sourbloom. This gives them incredible nutritious value.", completion = "The meat to sourbloom ratio is just right.", objectives = "Collect 2 Perfectly Tender Turtle Meat, 6 Reptilian Eggshells, and 15 Sourbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65901] = { id = 65901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneaking Out", description = "I'm grounded indefinitely! Doesn't my Ohn know I'm turning sixteen next spring? I should be able to leave when I want to.\n\nYou look like you could help me out. I do have an escape plan: by channeling these totems, I'll concentrate the air and create quite a stir. But I can't go around placing them, because I'm under maximum wind watch. Even Togo won't help me.\n\nBut with your help... Please! I promise I'll show you something cool.", progress = "If you rat me out, I'll haunt you with the windiest ghost--FOREVER! Don't do it!", completion = "Whew, thank you! Freedom!", objectives = "Place the air totems in Ohn'iri Springs and then inform Radiya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65902] = { id = 65902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food or Floof", description = "Look at this juicy and delectable herbed turtle meat! I speak objectively, of course. I'm a vegetarian.\n\nGo on! He probably hasn't had a meal all day.", progress = "Go, before the meat gets old!", completion = "Oh dear. We heard his outburst. Are you okay?", objectives = "Bring the Herbed Turtle Meat and Glade Hoppers to Theramus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65903] = { id = 65903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Beat Fluffy", description = "Poor Theramus. I have an idea to cheer him up!\n\nTake this net to catch some of the native hoppers, which are docile but quick. They've made quite a home by the coast.\n\nWe'll bring them to Theramus. He'll literally be overrun with fluffy goodness!", progress = "They are impossibly soft! I could spend all day petting them.", completion = "So! Many! Hoppers! Let's pet them all!", objectives = "Catch 12 Glade Hoppers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65904] = { id = 65904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Is Enough", description = "Grumpy or not, Theramus has a job to do. While he hides inside, he can't see the consequences of his absence.\n\nLet's go together. We'll show him the evidence.", progress = "This would convince anyone that the grove needs help, now!", completion = "...I think it worked? He left the cave!", objectives = "Bring the evidence of Lilac Ramble's damage to Theramus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65905] = { id = 65905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Weeds", description = "Perhaps it's best we give Theramus some space. \n\nBut we can't be idle. The grove is destroying itself at a rapid rate! Please help us out.", completion = "Thank you, {race}.", objectives = "Clear out overgrowth and monsters in Lilac Ramble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65906] = { id = 65906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disgruntled Initiate", description = "I received an interesting letter from Ohn'iri Springs.\n\nAs for the letter's contents, it details, quote, horrid imprisonment, controlling mentors, and extreme boredom. It is formally signed by Initiate Radiya. There's also a sketch of an eagle... kicking a centaur named Meluun off a cliff.\n\nWell. I suppose this is a call for help, if you are so inclined to see for yourself. To be frank, I think Radiya is probably okay. She sends me such letters often.", completion = "Who are you? Ordven sent you? He actually reads my letters?!\n\n<Radiya snorts with surprise and pleasure.> Thank Ohn'ara!", objectives = "Speak to Initiate Radiya at Ohn'iri Springs in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65907] = { id = 65907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favorite Fruit", description = "Mystic training is so boring. I'm watching water be wet half of my days. My brothers are already out in the wild hunting drakes and primalists, and making a difference in the world.\n\nAnyway, I promised I'd show you something cool! Did you know mudstompers love bushfruit? It grows nearby, among the geysers. Go pick some and we can feed them together.", progress = "I used to really like bushfruit until I had too much one day.\n\nMy whole body was shivering, like a bad cold, and my breath was minty for days after.", completion = "Seems like they like you! Or just the fruit. That's okay too. <Radiya winks.>", objectives = "Forage Wild Bushfruit from the Ohn'ir Geysers and feed them to 6 Lounging Mudstompers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65911] = { id = 65911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Alignment", description = "The bonds of this community... the friendship and family they share. \n\nI... never had that. The blue dragonflight never had that. And maybe that's because we haven't had a chance to. \n\nNow is the time. I must gather my kind. \n\nMeet me at the Azure Archives. There is much to be done.", completion = "I never expected to learn so much from the tuskarr. I think I'll visit when I can, and maintain those bonds of friendship.", objectives = "Return to Kalecgos in the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65913] = { id = 65913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wotcher, Watcher?", description = "Thank the Titans! {class}, we need your help!\n\nPrimalists attacked only moments ago. My sisters and I were able to defend, but at a severe loss...\n\nThere will be time to mourn after my watcher is safe! A group of Primalists broke away while we were fighting and I swear if they hurt our Watcher--\n\nYou must help her before it's too late!", completion = "Thank you, {race}. Were it not for your aid, I would have surely perished.", objectives = "Rescue Watcher Mara from the Primalists in Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65914] = { id = 65914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammoths Matter", description = "Our tribe has proudly nurtured the On'tuq mammoth herd for generations. Now they're... gone. \n\nTheir souls will linger in rage, after such a massacre. We must honor their lives by making good use of their remains.\n\nThere's too many for us to gather alone. Please, gather what materials you can from the youngsters and matriarchs, then meet me in the Kauriq Gleamlet.", progress = "My children had already picked out calves to foster into companions. How will I tell them?", completion = "With these remains, I think we can make something truly special... something that will put the souls of the mammoths at ease.", objectives = "Collect On'tuq Hide Scraps and On'tuq Tusks from fallen On'tuq Mammoths near the Kauriq Gleamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65916] = { id = 65916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Don't Negotiate with Primalists", description = "The Primalists thought they were able to overcome the might of Tyr. They were wrong. \n\nMy refti were able to track down the Primalists to a cave not far from here. As I thought, they have the missing keystones. \n\nChampion, if we are to restore the reservoir, we must get those keystones back.\n\nFurthermore, their leader must be slain so that they won't attempt a second assault.", progress = "Surely once we get the keystones back, Zuttiki will not look so... Dismal.", completion = "Thank you, {name}. Our final task of restoring the wards awaits.", objectives = "Slay Primalist Leader Ko'jo and retrieve the Missing Keystones in Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65918] = { id = 65918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventative Maintenance", progress = "Mara, my sisters? This wasn't supposed to happen.", completion = "Thank you, {name}. That should hold them at bay for now.", objectives = "Kill 8 Unleashed Elementals in Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65920] = { id = 65920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Ward!", progress = "Once all three wards are repaired, return here to activate the ward console.", completion = "Excellent work, {name}. The wards have been restored, and Tyrhold Reservoir is once again protected. Thank you for all you have done. Thaldraszus owes you a great debt.", objectives = "Use the Missing Keystones to repair the reservoir wards, then activate the console.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65921] = { id = 65921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refti Retribution", progress = "I knew this day could always come, I just hoped that it would not.", completion = "I will always feel pain for those we lost, but I am thankful for the ones we rescued.", objectives = "Kill Primalists and rescue refti in Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65925] = { id = 65925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Cullers", description = "These wyrms don't belong here. I don't know what's driven them from their underground lairs, but there's no way to help them, now.\n\nWe can't allow them to destroy the native life here.\n\nSlay the wyrms, {name}. Keep their parts, if you must, and find me in the Gleamlet when you're done.", completion = "It's a pity to wipe out any natural life... even troublesome ones.", objectives = "Slay Ice Slitherers and Ice Borers near the Kauriq Gleamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65926] = { id = 65926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tackling the Falls", description = "Have you heard the tale of the Gleamfisher? She built a boat strong enough to pass down waterfalls! \n\nElder Nava loves to tell the story.\n\nI think the noble spirits of the On'tuq mammoths would be honored if we used their remains to craft such a boat again.\n\nMy brother says no. But if we succeed, we can help bring fish to our struggling sister tribes.\n\nYou've proven your skill and passion! Together, I'm sure we can build something great.", completion = "Ruriq is as stubborn as ever.", objectives = "Help Ruriq build The Fallstrider.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65928] = { id = 65928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayward Winds", description = "Bah! Work together, she says? \n\nBut... if the Gleamfisher believes there is a chance we can help the other tribes... we must try. \n\nFor the wind spirit Kraunot to acknowledge us, we will first have to tend to his element. The nearby wind elementals have been agitated ever since the land began to awaken.\n\nWhile I inspect this boat you two made, you go and fight to dismantle them, then bring me their restless motes. That should bring some calm back to the area.", progress = "Don't worry, these wind elementals being here simply means they are riled up. By destroying them, we will restore some peace to the winds here.", completion = "I will tend to these motes, so they dissipate harmlessly. Kraunot will be pleased.", objectives = "Collect 10 Restless Wind Motes from Restless Winds near the Kauriq Gleamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65929] = { id = 65929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Breakers", description = "I knew the ancestor would approve!\n\nI don't know much about spirits -- Kauj is the shaman. But we will need to appease the great Spirits of Air and Water before they will appear to us. \n\nAnyone could see water elementals up the mountain slowly freezing. It is not a natural freeze. Cold has been coming down the mountains more than usual, lately. Left be, our entire river could ice over.\n\nRelease them from their icy prisons!", progress = "We welcome the natural shift of the earth, but this encroaching ice... it threatens our entire home.", completion = "Excellent. Otu'rorq, the local River Spirit, will be pleased to know his river will continue to flow, for now.", objectives = "Break Freezing Waters from ice near the Kauriq Gleamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65930] = { id = 65930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wrestle of Wind and Water", description = "Now we should be able to face the Spirits.\n\nDid Ruriq fail to mention it? By our tribe's traditions, we must face the Spirits in combat before asking a boon of them. The strength of their blessing is dependent on how well you impress them. \n\nPerhaps that is why the Gleamfisher insisted we all work together.\n\nIf you take on Kraunot, the Spirit of Air, Ruriq and I will tackle Otu'rorq, the Spirit of Water.\n\nThey dwell in the cave behind the nearby waterfall. We will meet you there, adventurer.", progress = "We must impress those spirits if Ruriq's vision is to come to life.", completion = "With how much older he is, Kauj has always been almost... more a father than a brother. \n\nI thought getting older and starting my own family would make me feel less like I needed him. \n\nI was wrong. Even before my wife passed, I was wrong.", objectives = "Face Kraunot, the Spirit of Air, near the Kauriq Gleamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65935] = { id = 65935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching Up to Chromie", description = "You have helped us regain our hold on the sands, but I can sense something greater happening up on the temple platforms. Let us take to the skies and regroup with Ambassador Chronormu there.\n\nAs always, time is of the essence.", completion = "About time! Eternus might look frozen in that bubble, but she's struggling with all her might to get free.", objectives = "Meet with Chromie on the Temporal Conflux platforms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65937] = { id = 65937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Negligence", description = "We can't give up. He must understand what's happening out here! If he won't leave the cave, we'll show him directly.\n\nAnything will do, I'm sure. There's so much going wrong, from the corrupted flora to the antagonized wildlife!", progress = "It's terrible to see the grove, and Theramus, in such a state.", completion = "You've returned!", objectives = "Find and then show evidence of the Lilac Ramble's damage to Theramus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65938] = { id = 65938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Once and Future Team", description = "All right! Let's pop that stasis bubble around the temple doors and release our Wardens! Are you ready for a huge tug-of-war match with time itself?\n\nYank at the door's bubble like you did with the crystals earlier. But be careful, all the time energy released is sure to collect and attack you. I'm not sure what will be there, but at least you'll have the freed Wardens on your side no matter what happens.\n\nGood luck, {name}!", progress = "We really should've foreseen this when we built our security system all that time ago...", completion = "That's the second largest time elemental I've ever seen! I knew I should have packed my S.E.L.F.I.E Camera today.\n\nOh well! I'll just stop by this moment again on my next day off.", objectives = "Use your Timewalker Staff to pop the temple door's stasis bubble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65939] = { id = 65939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Courage of One's Convictions", description = "The next battle will no doubt be fierce, but our courage and determination will overcome their greater numbers.\n\nI am counting on your exceptional skills to help lead the troops to victory.\n\nWe shall begin the assault when you are ready.", progress = "Have we secured the Citadel.", completion = "Excellent, {name}! The djaradin forces are on the run! We control the upper courtyard of the citadel. However, the vaults below may take much longer to secure.", objectives = "Gain control of the Obsidian Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65940] = { id = 65940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Broken Road", description = "I hope you don't mind getting your feet wet. The next leg of our journey will take us across two rivers.\n\nOhn Seshteng would like to share a story with you about our blessed watcher, Ohn'ahra. I happily leave you under her watch.", completion = "I sense something on the wind.", objectives = "Travel with the Shikaar caravan to the river crossing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65943] = { id = 65943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Offensive", description = "Khadgar and I are doing our best to hold off the Primalists in the sky, but we can't push further towards the tower.\n\nWe need you to weaken their ground forces so we can get closer to Raszageth and stop her before it's too late.\n\nMake your way through the Primalists ahead. If I can maintain my concentration, there'll be another mirror image waiting.", completion = "Good work, some of their forces are diverting from above.", objectives = "Defeat 15 Primalists within Vakthros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65944] = { id = 65944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lava Burst", description = "The Primalists have torn apart the mountain to send their forces streaming to Vakthros!\n\nI spied some lava orbs in the initial corridor that they're using to spread more of their elemental chaos.\n\nDestroy them to help slow their advance. I'll do what I can from up here to help Kalecgos.", completion = "That should slow them down a bit. It seems I'm getting a bit rusty compared to the fight with the Burning Legion...", objectives = "Destroy 3 Lava Orbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65947] = { id = 65947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time-Locked Timewalkers", description = "I'm so glad you're here! I need you to stabilize the situation here on the platforms while Dante and Zera help me hold our infinite dragon friend in place.\n\nThe temple's security measures locked Eternus in a stasis bubble when she tried to take control of our Oathstone. Unfortunately, the other Timewalkers were also caught in those security measures.\n\nYour Timewalker staff should free them, no problem. Just make sure to deal with any angry timelings that pop up!", progress = "We can't have our Temple visitors rest inside of stasis bubbles when they get here.\n\nOh, wait! Maybe that's exactly what we should do! I'll write it down for later, {name}.", completion = "It worked? I'm not surprised... not entirely, at least!", objectives = "Free 8 Timewalkers from Time Bubbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65948] = { id = 65948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracks in Time", description = "When the temple locked down, the Wardens got sealed up with the temple doors. We need to pop that stasis bubble to get them out! Unfortunately, that'll need a fully empowered Timewalker staff...\n\nI know! You can drain the crystals here on the platforms! That should power up your staff enough.\n\nThey have their own stasis fields, so just yank them out and absorb their energy with your staff.\n\nAnd don't feel bad if they shatter--the power is still there, even if it's in pieces!", completion = "Excellent work!\n\nYou should be cooking with more than enough time juice to release the Wardens now!", objectives = "Use the East and West crystals to further empower your Timewalker Staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65949] = { id = 65949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sole Mender", description = "When we join Ohn'ahra in the wind, we leave these medallions behind.\n\nAlthough I helped craft this medallion, I am not its rightful owner.\n\nIt should be returned to Roscha. It is the last memory of her betrothed.\n\nTake it to her so she may mourn and be at peace.", completion = "Is this... ah. It is. My beloved is in the sky, then, running with Ohn'ahra. I will join her... in time.\n\nThank you, {name}. \n\nI will remember what you have done for Clan Shikaar. And for me.", objectives = "Return the Medallion to Farrier Roscha.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65950] = { id = 65950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Gorlocs", description = "Is Farrier Roscha invited to the caravan? No! But who must provide shoes for the caravan? Farrier Roscha. And from whom do the Mudfins steal? Of course, Farrier Roscha. Pah.\n\nI would send Khasar, but who knows where he has wandered this time? \n\nFind my supplies. Teach those thieving creatures not to steal from Farrier Roscha.\n\nGo!", progress = "There are too many gorlocs around us. We're not safe here.", completion = "Roscha sent you? She must be furious.\n\nShe has been through so much already. I could not return without securing all that was lost.", objectives = "Return the stolen supplies from the Mudfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65951] = { id = 65951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sole Supplier", completion = "Thank you, {name}. Let's get to work.", objectives = "Search the woods for Khasar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65952] = { id = 65952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chief of Legends", description = "The gorlocs of this swamp were once simple creatures. Pests, perhaps, but never raiders, thieves, or dog-eaters.\n\nIt is their chief, Grrlgllmesh, who has led them away from their nature.\n\nPut an end to him, and the gorlocs will threaten us no more.", progress = "Chief Grrlgllmesh is a scourge to these lands.", completion = "With their chieftain slain, the gorlocs will no longer bother us. \n\nI am astounded by how strong they became under Chief Grrlgllmesh. \n\nI have never seen such primitive creatures rise up against a mighty civilization like ours before. Are we not so different? So much further evolved? I suppose not...", objectives = "Kill Chief Grrlgllmesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65953] = { id = 65953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ora-cull", description = "Of all the madness in this gorloc village, I have discovered none so troubling as the gorloc shamans.\n\nThey are particularly vicious and play recklessly with storm magic with no regard for the consequences. \n\nThis must be put to an end. Slay them, and bring me their totems. Our mystics will be interested in them.", progress = "The gorloc shamans have gone too far.", completion = "<Khasar frowns at the totems.>\n\nThese totems are for storm magic. Storm magic is sacrilege to the gift of winds given by Ohn'ahra herself.\n\nI will deliver these to the mystics.", objectives = "Collect 4 totems from gorloc shamans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65954] = { id = 65954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release the Hounds", description = "I have heard the familiar howls and barks of bakar that are missing from camp.\n\nOur beloved dogs are trapped in cages, waiting to be ripped apart by those... those things.\n\nWe have a duty to our companions. Free them and witness the true might of a Shikaar bakar!", progress = "The gorlocs of this village will learn to fear our bakar.", completion = "Magnificent beasts, aren't they?\n\nEvery bakar holds a special place in Clan Shikaar. They are our fellow hunters, guards, and our most cherished friends.", objectives = "Free the Shikaar Bakar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65955] = { id = 65955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Centaur's Best Friend", progress = "Together, Baba and I are one hunting unit greater than all the rest.", completion = "Thank you, {name}. We are safe in here and can speak freely. \n\nI will protect Baba from any gorlocs that dare venture in while he rests.", objectives = "Free Khasar and meet him in the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65956] = { id = 65956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon Strike", description = "With your help, my Blacktalon assassins will cut down the djaradin defending the outer perimeter. Mark any targets with a small stun bomb, and they will come to your aid.\n\nProceed quickly and eliminate anything that may hinder our advance.", progress = "Have you eliminated their defenses?", completion = "Our advance is pushing them back! All that remains is to breach the gates.", objectives = "Djaradin defenses disrupted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65957] = { id = 65957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time for Heroes", description = "From what we have observed, djaradin society is built on strength. The strongest serve as examples for others to fight all the harder. \n\nAmong the forces below are three examples of the mightiest djaradin... and your targets.\n\nYou, {name}, will personally eliminate them. This should deal a devastating blow to their morale.", progress = "Have you defeated your targets?", completion = "You've proven yourself the true hero of the day, {name}.", objectives = "Slay Modak the Flamespit, Piercer Gigra, and Olphis the Molten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65958] = { id = 65958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Power", description = "I'm afraid it's becoming harder to maintain my mirror images. The Primalists are focusing their efforts to tearing me out from the sky.\n\nNot to worry... I have a plan.\n\nI need you to take the orb you recovered and gather elemental magic from slain Primalists. \n\nWe'll need that elemental power up ahead to divert their forces away from me.", progress = "We must act quickly.", completion = "That orb is brimming with power! That will be perfect for what's next.", objectives = "Use the Elemental Focus to drain elemental energy out of slain Primalists and elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65962] = { id = 65962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Never-Final Countdown", description = "I never thought I'd save our temple by dismantling the very security we set up to protect it, but here we are!\n\nWith the time elementals purged, our Timewalkers free, and our Wardens at the ready, it's finally time to let this last stasis bubble down and deal with Eternus.\n\nLet me know when you're ready. I know with you by my side nothing can go wrong.", completion = "Eternus and Chromie have fallen through space and time. We must retrieve them at all costs!", objectives = "Speak to Chromie when ready.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65977] = { id = 65977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirin Tor Recovery", description = "When the Primalists attacked our expedition, I feared many of our mages were lost to us.\n\nIt seems they were taken by the Primalists and are being tortured as we speak!\n\nPlease, you must rescue the mages left here. They may not be able to help in this fight, but we cannot leave them behind!", progress = "We must aid those mages.", completion = "You have my thanks. We cannot forsake anyone in this fight.", objectives = "Rescue 6 Dying Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65989] = { id = 65989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invader Djaradin", description = "We may not have the power to take back our outpost, but we do not have to surrender without a fight.\n\nShow them we still have teeth.", progress = "The djaradin had not been seen for generations. We were... unprepared.", completion = "Wonderful.", objectives = "Kill 6 djaradin at the Dragonheart Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65990] = { id = 65990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver Whelps From Evil", description = "They descended upon us before we could even respond. My guards held as long as they could as we evacuated the young and helpless, but I fear that there are more within the outpost.\n\nCross that bridge and search for survivors.", progress = "We will take back the town as soon as we can muster the forces... but for now, the lives of our people must be our priority.", completion = "We cannot rest yet, but I breathe easier knowing we have rescued them. Thank you.", objectives = "Save 4 Whimpering Whelplings from Dragonheart Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65991] = { id = 65991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for a Reckoning", description = "Cadet Sendrax has informed me of our majordomo's plans. Thank the Life-Binder that we have their help. Their interference gives us the reprieve we need to get our wounded back to the Life Pools to be treated.\n\nI wish I could reinforce Selistra but I must keep my guards near the wounded. Go to the enemy stronghold to meet them. \n\nIf there were another way of handling the djaradin, I would ask it. But, as it were...\n\nYou must do what you must.", completion = "It does my heart well to hear such good news from Dragonheart Outpost during such a terrible time. The refugees will be safe at the Life Pools.\n\nEven the djaradin would not raise arms against the might of Queen Alexstrasza herself.", objectives = "Meet Wrathion and Majordomo Selistra at Scalecracker Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65992] = { id = 65992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacktalon Intel", description = "While Selistra and I attracted their eyes above, shadows crept in through their defenses.\n\nMy agents, the Blacktalon, are keeping an eye and an ear throughout the keep. Meet them and let them know you're on our side. They'll give you some valuable information on our enemies.", progress = "I've put my life in their hands. You can trust them.", completion = "That is troubling, to say the least. Yet another reason to fight them.", objectives = "Speak to Wrathion's spies hidden around Scalecracker Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65993] = { id = 65993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killjoy", description = "Ah, yes.\n\nI saw the leader of these giants headed back from the raid shortly after I arrived. She's celebrating their victory somewhere within the camp. \n\nIt would be a shame if someone interrupted her revelries, don't you think?", completion = "The djaradin seem to have no shortage of bodies to throw in our way... but perhaps this blow shall give them pause. Well done, friend.", objectives = "Kill Meatgrinder Sotok at Scalecracker Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65994] = { id = 65994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Djaradin Djustice" }
quests[65995] = { id = 65995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obsidian Citadel", description = "<At a glance, this seems to be internal communications between djaradin camps.\n\nThe words 'Obsidian Citadel' leap out at you.\n\nPerhaps Wrathion would be interested in seeing this.>", completion = "A treat! I love seeing into the minds of my enemies. Helps me strike fast, strike true.\n\nLet's see...\n\nThe Obsidian Citadel?\n\nNo.\n\nNo!", objectives = "Give the Qalashi Plans to Wrathion.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65996] = { id = 65996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Reinforcements", description = "Commander Lethanak was insightful, as always. We will need the help of our most veteran guards to stop their threat. Rallying them was the perfect task for a young cadet like Sendrax, but she may need support.\n\nSendrax's path will take her towards the west, which may have been overwhelmed by this rising threat. They will need aid as well. Take this concoction and give them your support.", progress = "We are all in this together, {name}. The safety of the isles is at stake.", completion = "Sendrax stopped by and rushed through. That one is a whirlwind.\n\nI like her.", objectives = "Help the injured guards and find Sendrax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65997] = { id = 65997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Sendrax", description = "Cadet Sendrax came through here not long ago.\n\nShe relayed Commander Lethanak's orders for all drakonid to rally back at the Life Pools. Our whole defensive regiment set off in that direction not long after.\n\nBut our scouts were out on patrol in the old ruins, so she headed in there to rally them too.", progress = "Keep low, {name}.", completion = "I haven't read anything in the archives about the Primalists stealing dragon eggs before.\n\nThis is bad. Very bad.", objectives = "Find Sendrax in the Life-Binder Conservatory ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65998] = { id = 65998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Future of the Flights", progress = "Such cruelty and selfishness... I cannot even fathom.", completion = "<Sendrax is clearly shaken by what she had to do.>\n\nDeath was the only mercy left to those poor whelplings...", objectives = "Rescue the Ruby Dragon Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[65999] = { id = 65999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red in Tooth and Claw", description = "Commander Lethanak warned us recruits that he had received reports of the Storm-Eater, Raszageth, escaping her prison. It seems her servants have followed in her wake, threatening all we hold dear.\n\nThey move quickly. These ruins were reported to be abandoned during the last patrol.\n\nWe must stop the Primalists here.\n\nFor the Life-Binder, and for all of the dragonflights!", progress = "The dragonflights will prevail against the Primalists.", completion = "<Sendrax pats out a lingering flame on her armor.>\n\nWe've done what we could. What was needed.", objectives = "Kill 15 Primalist invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66000] = { id = 66000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Library of Alexstrasza", description = "<The pages on this book are charred.\n\nThe Primalists seem to be burning the ancient tomes found here, putting the dragonflights' very history in peril. It's as if the Primalists want to erase the dragonflights from history.\n\nSave what you can.>", progress = "I smell burning parchment on the wind...", completion = "Our history will survive.", objectives = "Save 4 works of cultural significance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66001] = { id = 66001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Last Hope", completion = "Is that...?", objectives = "Rescue the last Infused Dragon Egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66003] = { id = 66003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rings To Bind Them", description = "The djaradin here have become bold, binding flame elementals and letting them rampage through the area. The wildlife has fled, and the elementals are dangerously close to our camps.\n\nLuckily, I have been able to construct a small bastion of stone to stand against this fiery tide the djaradin have unleashed... and we will not fall!\n\nGather the magical rings that bind these flame elementals. We shall use them to bolster our defenses against the flame elementals.", progress = "Have you gathered all the rings I asked for?", completion = "Perfect! The residual energies of these rings can be turned against their creators to summon a construct under our control!", objectives = "Gather 12 Molten Binding Rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66004] = { id = 66004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgresh" }
quests[66005] = { id = 66005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medallion of a Fallen Friend", description = "<This chewed up hunk of metal was once a beautiful ornament of great importance to a Shikaar centaur. \n\nKhasar may know more about the owner.>", completion = "This medallion is all that remains of a dear friend of mine who ventured too far into the swamp this past season. I thought it lost to the elements.\n\nI cut this leather from her first mammoth hunt. We were children, then.", objectives = "Return the Medallion of a Fallen Friend to Khasar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66006] = { id = 66006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Roscha", description = "Baba is rested, and Roscha's supplies are recovered. We can return without upsetting her further. \n\nTake some boxes when you go. I will send warriors for the rest.", progress = "What took you so long?", completion = "You have the supplies? Good.\n\nLeave them by the forge.\n\n<Roscha looks around and frowns.>", objectives = "Return the supplies to Farrier Roscha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66007] = { id = 66007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Air", description = "The Primalists are using these massive orbs here to hold off Kalecgos. \n\nAt this rate, Kalecgos will be too injured to continue the fight. If he falls, I won't be able to fend off Raszageth.\n\nThe empowered gem you hold should allow you to disguise yourself as an elemental to sneak ahead.\n\nUse the gem to destroy the orbs. That should give Kalecgos room to unleash his power.\n\nI will focus my attention on shielding the tower from Raszageth.", completion = "Thank you, {name}. Now it's time to show the Primalists the true might of the Aspect of the blue dragonflight!", objectives = "Destroy 4 Lava Beacons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66009] = { id = 66009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Vakthros", description = "It's time, {name}. The Primalist forces in the air are dwindling now that you've handled things on the ground.\n\nRaszageth is calling in one of her lieutenants to reinforce the Primalist forces, thanks to your efforts.\n\nI need you to handle this monster while I push forward to fight Raszageth and help Khadgar.\n\nLook for my magic during your fight. I will do what I can to aid you.\n\nIt is time for Raszageth to face the fury of the Aspect of magic!", completion = "Good to see you adventurer. Time is of the essence!", objectives = "Defeat Korthrox the Destroyer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66011] = { id = 66011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Memory of Ysera", description = "Oh, no! Now I think I understand. Theramus...he misses Ysera, and she can't come back.\n\nCome! I suspect I know where he went. We won't bother him further, but it'll be good to tell him that we're sorry, and that we'll give him the space he wants.\n\nWe are here for each other, within the nature all around us.", progress = "We appreciate you sticking around, {race}. You've been a great help.", completion = "<Theramus looks quietly upon the newly restored shrine.>", objectives = "Find Theramus again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
